async function shot( name, pos, target, frames = 30 ) {

	L.camera.position.copy( pos );
	L.camera.lookAt( target );
	await L.run( frames, ( dt ) => {

		step( dt );
		if ( typeof target === 'function' ) L.camera.lookAt( target() );

	} );
