@compute @workgroup_size( 1 )
fn main() {
	let n = 48u;
	let base = sprayReserve( n );
	for ( var i = 0u; i < n; i++ ) {
		let slot = spraySlot( base, i );
		let r0 = sprayRand( i, 11u ); let r1 = sprayRand( i, 12u );
