		let kind = select( SPRAY_DROPLET, SPRAY_MIST, i < 2u );
		sprayWrite( slot, vec3f( -6.0, 0.1, -2.0 ), v, select( 0.005, 0.5, i < 2u ), kind, 2.0, 1.0 + r1 * 0.999 );
