		spray.emit( V( - 3, 0.1, 0 ), V( 1.5, 6, 0 ), 12, 0.012, SPRAY.LIGAMENT, { spread: 0.8, jitter: 0.1, life: 1.5 } );
		if ( f % 4 === 0 ) spray.emit( V( 0, 0.2, 0 ), V( 0, 3.5, 0.5 ), 20, 0.25, SPRAY.SPRAY, { spread: 1.5, jitter: 0.3, life: 2.2, sizeJitter: 0.8 } );
