		spray.emit( V( 3, 0.1, 1 ), V( 0.5, 3.2, 1 ), 20, 0.06, SPRAY.SHEET, { to: V( 4, 0.1, - 1 ), spread: 0.4, jitter: 0.03, life: 1.2 } );

