// Shared setup for the sky stream tests (headless): atmosphere + sky (+ clouds) rendered as the
// scene background into a SceneRenderer, tonemapped (ACES + exposure) into an rgba8 target.
import { writePNG } from './headless.mjs';
import { GPU } from '../src/engine/gpu/GPU.js';
import { RenderTarget } from '../src/engine/gpu/Texture.js';
import { readTexture } from '../src/engine/gpu/Readback.js';
import { FrameUniforms, G, setFrameCamera } from '../src/engine/render/Frame.js';
import { FullscreenPass } from '../src/engine/render/FullscreenPass.js';
import * as E from '../src/engine/index.js';

export { GPU, G, E, FrameUniforms, setFrameCamera, writePNG, readTexture, RenderTarget };

// same key light logic as App.updateSun / applyAtmosphereReadback
export function setTimeOfDay( app, hours, sunDirectionFromTime, SUN_ILLUMINANCE ) {

	const dir = sunDirectionFromTime( hours );
	app.atmosphere.sunDir.value.copy( dir );
	const night = E.MathUtils.smoothstep( - dir.y, 0.02, 0.18 );
	G.night.value = night;
	app.sky.starIntensity.value = night;
	const moon = new E.Vector3( - dir.x, Math.abs( dir.y ) * 0.8 + 0.25, - dir.z ).normalize();
	app.sky.moonDir.value.copy( moon );
	G.sunDir.value.copy( dir.y > - 0.07 ? dir : moon );
	app._sunUp = dir.y > - 0.07;
	app._SUN_E = SUN_ILLUMINANCE;

}

export function applyReadback( app ) {

	const a = app.atmosphere;
	if ( ! a.sunTransmittance ) return false;
	const sunTrue = a.sunDir.value;
	const T = a.sunTransmittance;
	const horizonFade = E.MathUtils.smoothstep( sunTrue.y, - 0.03, 0.02 );
	if ( app._sunUp ) G.sunColor.value.setRGB( T[ 0 ], T[ 1 ], T[ 2 ] ).multiplyScalar( app._SUN_E * horizonFade );
	else G.sunColor.value.setRGB( 0.6, 0.7, 1.0 ).multiplyScalar( 0.12 * G.night.value );
	const irr = a.skyIrradiance;
	const nightAmb = 0.012 * G.night.value;
	G.skyIrradiance.value.setRGB( irr[ 0 ] + nightAmb * 0.6, irr[ 1 ] + nightAmb * 0.7, irr[ 2 ] + nightAmb );
	G.horizonColor.value.setRGB( a.horizon[ 0 ], a.horizon[ 1 ], a.horizon[ 2 ] );
	return true;

}

let _tonemap = null;
let _src = null;
export function tonemapPass( srcTex ) {

	_src = srcTex;
	if ( ! _tonemap ) _tonemap = new FullscreenPass( { label: 'test tonemap', colorFormats: [ 'rgba8unorm' ], bindings: { hdr: { texture: () => _src } },
		code: /* wgsl */`
fn RRTAndODTFit( v: vec3f ) -> vec3f {
	let a = v * ( v + 0.0245786 ) - 0.000090537;
	let b = v * ( 0.983729 * v + 0.4329510 ) + 0.238081;
	return a / b;
}
fn aces( c: vec3f ) -> vec3f {
	let ACESInputMat = mat3x3f( vec3f( 0.59719, 0.07600, 0.02840 ), vec3f( 0.35458, 0.90834, 0.13383 ), vec3f( 0.04823, 0.01566, 0.83777 ) );
	let ACESOutputMat = mat3x3f( vec3f( 1.60475, -0.10208, -0.00327 ), vec3f( -0.53108, 1.10813, -0.07276 ), vec3f( -0.07367, -0.00605, 1.07602 ) );
	var color = c / 0.6;
	color = ACESInputMat * color;
	color = RRTAndODTFit( color );
	color = ACESOutputMat * color;
	return sat3( color );
}
fn fragment( in: FSIn ) -> vec4f {
	let c = textureLoad( hdr, vec2i( in.pos.xy ), 0 ).rgb * frame.exposure;
	return vec4f( linearToSrgb( aces( c ) ), 1.0 );
}` } );
	return _tonemap;

}

export async function savePNG( tex, path, crops = [] ) {

	const img = await readTexture( tex );
	const w = tex.width, h = tex.height;
	const rgba = new Uint8Array( img.data );
	writePNG( path, w, h, rgba );
	// crops: [ { x, y, w, h, name } ] saved next to it (zoomed inspection)
	for ( const c of crops ) {

		const out = new Uint8Array( c.w * c.h * 4 );
		for ( let y = 0; y < c.h; y ++ ) out.set( rgba.subarray( ( ( c.y + y ) * w + c.x ) * 4, ( ( c.y + y ) * w + c.x + c.w ) * 4 ), y * c.w * 4 );
		writePNG( path.replace( '.png', `-${ c.name || 'crop' }.png` ), c.w, c.h, out );

	}

	console.log( 'wrote', path );

}

export function wait( ms ) {

	return new Promise( ( r ) => setTimeout( r, ms ) );

}

// GPU cost of the sky stream per pass (timestamp queries), steady state at 2560x1267.
// usage: node test/sky-perf.mjs [W] [H]   (the GPU is shared with other agents: numbers are noisy)
import { GPU, G, E, setFrameCamera, setTimeOfDay, applyReadback, wait } from './sky-harness.mjs';
import { Atmosphere, SUN_ILLUMINANCE } from '../src/sky/Atmosphere.js';
import { Sky, sunDirectionFromTime } from '../src/sky/Sky.js';
import { Clouds } from '../src/sky/Clouds.js';
import { Environment } from '../src/sky/Environment.js';
import { MeshRenderer } from '../src/engine/render/MeshRenderer.js';
import { SceneRenderer } from '../src/engine/render/SceneRenderer.js';

await GPU.init( { headless: true } );
if ( ! GPU.hasTimestamp ) {

	console.log( 'no timestamp-query' );
	process.exit( 0 );

}

const W = Number( process.argv[ 2 ] || 2560 ), H = Number( process.argv[ 3 ] || 1267 );
const atmosphere = new Atmosphere();
const sky = new Sky( atmosphere );
const clouds = new Clouds( null, atmosphere );
clouds.outputSize = { x: W, y: H };
sky.clouds = clouds;
const scene = new E.Scene();
const env = new Environment( null, scene, sky );
if ( process.env.ENV_CONT ) env.interval = 0;
const camera = new E.PerspectiveCamera( 55, W / H, 0.1, 60000 );
const mr = new MeshRenderer();
const sr = new SceneRenderer( mr, scene, camera );
sr.setSize( W, H );
sr.background = process.env.NOBG ? null : sky.background;
const app = { atmosphere, sky };
setTimeOfDay( app, 15.5, sunDirectionFromTime, SUN_ILLUMINANCE );
camera.position.set( 0, 3, 0 );

// timestamp slots per labelled pass
const MAXQ = 256;
const qs = GPU.device.createQuerySet( { type: 'timestamp', count: MAXQ } );
const resolveBuf = GPU.device.createBuffer( { size: MAXQ * 8, usage: GPUBufferUsage.QUERY_RESOLVE | GPUBufferUsage.COPY_SRC } );
const readBuf = GPU.device.createBuffer( { size: MAXQ * 8, usage: GPUBufferUsage.MAP_READ | GPUBufferUsage.COPY_DST } );
let slots = [];
const tw = ( label ) => {

	const i = slots.length;
	slots.push( label );
	return { querySet: qs, beginningOfPassWriteIndex: i * 2, endOfPassWriteIndex: i * 2 + 1 };

};

// wrap every ComputeKernel.dispatch and the background pass
const kernels = [ ...Object.values( atmosphere ).filter( ( k ) => k && k.pipeline && k.dispatch ), ...Object.values( clouds ).filter( ( k ) => k && k.pipeline && k.dispatch ),
	...env.faceKernels, ...env.filterKernels.flat(), ...env.shKernels ];
const wrap = ( k ) => {

	if ( k._wrapped ) return;
	k._wrapped = true;
	const d = k.dispatch.bind( k );
	k.dispatch = ( c, o = {} ) => {

		k.timestampWrites = tw( k.label );
		d( c, o );
		k.timestampWrites = null;

	};

};

kernels.forEach( wrap );
const origRender = mr.render.bind( mr );
mr.render = ( s, p ) => origRender( s, { ...p, timestampWrites: tw( 'scene pass (sky background)' ) } );

const acc = {};
const FR = 90;
for ( let f = 0; f < FR; f ++ ) {

	slots = [];
	const a = f * 0.004;
	camera.lookAt( Math.cos( a ), 3.3, Math.sin( a ) );
	GPU.beginFrame();
	atmosphere.update( 1 / 60, camera.position.y );
	clouds.update( 1 / 60, camera );
	for ( const s of clouds._traceSets ) if ( s ) [ s.trace, s.high, s.box, ...s.resolve ].forEach( wrap );
	env.update( 1 / 60 );
	setFrameCamera( camera, W, H );
	sr.render();
	const enc = GPU.getEncoder();
	enc.resolveQuerySet( qs, 0, slots.length * 2, resolveBuf, 0 );
	enc.copyBufferToBuffer( resolveBuf, 0, readBuf, 0, slots.length * 16 );
	GPU.submit();
	await readBuf.mapAsync( GPUMapMode.READ );
	const t = new BigUint64Array( readBuf.getMappedRange().slice( 0 ) );
	readBuf.unmap();
	if ( f >= 30 ) {

		let lo = null, hi = null;
		for ( let i = 0; i < slots.length * 2; i ++ ) { if ( lo === null || t[ i ] < lo ) lo = t[ i ]; if ( hi === null || t[ i ] > hi ) hi = t[ i ]; }
		( acc[ 'FRAME SPAN (first begin .. last end)' ] = acc[ 'FRAME SPAN (first begin .. last end)' ] || [] ).push( Number( hi - lo ) / 1e6 );

	}

	if ( f >= 30 ) slots.forEach( ( l, i ) => {

		const ms = Number( t[ i * 2 + 1 ] - t[ i * 2 ] ) / 1e6;
		( acc[ l ] = acc[ l ] || [] ).push( ms );

	} );
	applyReadback( app );

}

let total = 0;
for ( const l in acc ) {

	const v = acc[ l ].slice().sort( ( x, y ) => x - y );
	const med = v[ v.length >> 1 ];
	const perFrame = v.reduce( ( s, x ) => s + x, 0 ) / ( FR - 30 );
	total += perFrame;
	console.log( `${ l.padEnd( 34 ) } median ${ med.toFixed( 3 ) } ms  x${ ( v.length / ( FR - 30 ) ).toFixed( 2 ) }/frame  avg/frame ${ perFrame.toFixed( 3 ) } ms` );

}

console.log( 'total per frame (avg)', total.toFixed( 3 ), 'ms' );
await wait( 100 );
process.exit( 0 );

// Dump the clouds' generated textures (weather, synoptic, fibres, a slice of the shape / detail volumes)
// as PNGs for comparison with the three.js version. usage: node test/sky-textures.mjs [outDir]
import { writePNG } from './headless.mjs';
import { GPU } from '../src/engine/gpu/GPU.js';
import { readTexture } from '../src/engine/gpu/Readback.js';
import { FullscreenPass } from '../src/engine/render/FullscreenPass.js';
import { Texture } from '../src/engine/gpu/Texture.js';
import { Atmosphere } from '../src/sky/Atmosphere.js';
import { Clouds } from '../src/sky/Clouds.js';

await GPU.init( { headless: true } );
const out = process.argv[ 2 ] || '/tmp';
const clouds = new Clouds( null, new Atmosphere() );
