	s.albedo = mix( vec3f( 0.62, 0.52, 0.36 ), vec3f( 0.16, 0.22, 0.07 ), t ) * ( 0.9 + 0.1 * sin( in.P.x * 3.1 ) * sin( in.P.z * 2.7 ) );` } ) );
