		for ( let l = 0; l < levels; l ++ ) {

			const r = leafSize * Math.pow( 2, l ) * rangeFactor;
			this.ranges.push( r );
			const start = prev + ( r - prev ) * morphStartRatio;
			morph.push( new Vector2( start, 1 / Math.max( 1e-3, r - start ) ) );
