		const Cap = P[ 0 ].toUpperCase() + P.slice( 1 );
		this.params = new UniformBlock( Cap + 'Params', {
			morph: [ `vec4f[${ levels }]`, morph.map( ( m, l ) => new Vector4( m.x, m.y, spacings[ l ], 0 ) ) ],
		}, { label: P } );
