		this.slot = {};
		_f.makeTranslation( PARK.x, PARK.y, PARK.z );
		FISH_IDS.forEach( ( id, i ) => {

			fp.add( 'whole', FISH[ id ].model, _f, 'side', 0.3, { cloudy: 0.08, wet: 1, seed: 0.37 } );
			this.slot[ id ] = i;

		} );
