			colorFormats: [ format ],
			code: ACES_WGSL + /* wgsl */`
fn fragment( in: FSIn ) -> vec4f {
	let n = i32( portrait.ss );
	let base = vec2i( in.pos.xy ) * n;
	var rgb = vec3f( 0.0 );
	var a = 0.0;
	for ( var y = 0; y < n; y++ ) {
		for ( var x = 0; x < n; x++ ) {
			let c = textureLoad( portraitSrc, base + vec2i( x, y ), 0 );
			let cov = sat( c.a );
			rgb += acesFilmicToneMapping( max( c.rgb, vec3f( 0.0 ) ) / max( cov, 1e-4 ), portrait.exposure ) * cov;
