		D[ o + 9 ] = curl; D[ o + 10 ] = 0; D[ o + 11 ] = jaw;
		fp.pos[ i * 4 ] = _p.x; fp.pos[ i * 4 + 1 ] = _p.y; fp.pos[ i * 4 + 2 ] = _p.z; fp.pos[ i * 4 + 3 ] = L;
		fp.batch.upload();

