	// ---- bake (chunked)
	_bakeStep() {

		const B = this._bake;
		if ( B.done ) return;
		const T = this.game.app.terrainData;
		const res = T.res, tex = T.texel, org = T.origin;
		const idx = ( x, z ) => {

			const i = Math.floor( ( x - org ) / tex ), j = Math.floor( ( z - org ) / tex );
