		f.rotation.y = this._yawOff + Math.sin( this._t * 0.37 ) * 0.05;
		f.rotation.z = Math.sin( this._t * 0.23 ) * 0.02;
		f.scale.y = 1 + Math.sin( this._t * 1.6 ) * 0.006;

	}

}

// Stand-in figure (~1.72 m, facing local +Z): a weathered islander in a hat, apron and boots.
// look: { shirt, trousers, apron, hat, hair, skin, beard } colours to tell the traders apart.
function buildFigure( look = {} ) {

	const P = [];
	const add = ( g, o ) => P.push( prepare( g, o ) );
	const SKIN = { color: look.skin ?? 0x9a6a4a, rough: 0.55, pattern: PAT.skin };
	const SHIRT = { color: look.shirt ?? 0x5d7a8c, rough: 0.9, pattern: PAT.cloth };
	const TROUSERS = { color: look.trousers ?? 0x3f4a3c, rough: 0.9, pattern: PAT.cloth };
	const APRON = { color: look.apron ?? 0xd8b24a, rough: 0.45 };
	const BOOTS = { color: 0xe8e2d0, rough: 0.5 };
	const HAT = { color: look.hat ?? 0xc9a86a, rough: 0.9, pattern: PAT.cloth };
	const HAIR = { color: look.hair ?? 0xb8b2a6, rough: 0.9 };
	const V = ( x, y, z ) => new Vector3( x, y, z );
	// legs and white rubber boots
	for ( const s of [ - 1, 1 ] ) {

		add( cylinder( 0.075, 0.068, 0.36, 10 ), { ...BOOTS, matrix: mat4( s * 0.1, 0.18, 0.01 ) } );
		add( cylinder( 0.068, 0.06, 0.08, 10 ), { ...BOOTS, matrix: mat4( s * 0.1, 0.04, 0.05, 0, 0, 0, 1, 1, 1.5 ) } );
		add( cylinder( 0.085, 0.072, 0.48, 10 ), { ...TROUSERS, matrix: mat4( s * 0.1, 0.6, 0 ) } );

	}

	// torso: a little barrel-chested, a slight stoop
	add( roundedBox( 0.38, 0.52, 0.24, 0.08, 3 ), { ...SHIRT, matrix: mat4( 0, 1.1, - 0.01, 0.06 ) } );
	add( roundedBox( 0.36, 0.14, 0.22, 0.06, 2 ), { ...TROUSERS, matrix: mat4( 0, 0.86, 0 ) } );
	// apron with bib and straps
	add( box( 0.34, 0.62, 0.012 ), { ...APRON, matrix: mat4( 0, 0.86, 0.125, 0.05 ) } );
	add( box( 0.24, 0.24, 0.012 ), { ...APRON, matrix: mat4( 0, 1.2, 0.132, 0.08 ) } );
	for ( const s of [ - 1, 1 ] ) add( rod( V( s * 0.1, 1.3, 0.13 ), V( s * 0.12, 1.36, - 0.1 ), 0.012, 4 ), APRON );
	// arms: sleeves rolled up, forearms resting forward
	for ( const s of [ - 1, 1 ] ) {

		add( rod( V( s * 0.22, 1.3, 0 ), V( s * 0.25, 1.02, 0.05 ), 0.055, 8, 0.05 ), SHIRT );
		add( rod( V( s * 0.25, 1.02, 0.05 ), V( s * 0.2, 0.92, 0.27 ), 0.045, 8, 0.04 ), SKIN );
		add( sphere( 0.045, 8, 6 ), { ...SKIN, matrix: mat4( s * 0.19, 0.9, 0.31 ) } );

	}

	// neck, head, ears, nose, grey hair and beard stubble
	add( cylinder( 0.055, 0.06, 0.1, 10 ), { ...SKIN, matrix: mat4( 0, 1.41, 0.01 ) } );
	add( sphere( 0.108, 14, 10 ), { ...SKIN, matrix: mat4( 0, 1.55, 0.02, 0, 0, 0, 1, 1.12, 1.02 ) } );
	add( sphere( 0.02, 6, 5 ), { ...SKIN, matrix: mat4( 0, 1.54, 0.13, 0, 0, 0, 1, 1.4, 1 ) } );
	for ( const s of [ - 1, 1 ] ) add( sphere( 0.025, 6, 5 ), { ...SKIN, matrix: mat4( s * 0.105, 1.55, 0.0, 0, 0, 0, 0.5, 1, 1 ) } );
	add( sphere( 0.112, 12, 8, 0, Math.PI * 2, Math.PI * 0.55, Math.PI * 0.3 ), { ...HAIR, matrix: mat4( 0, 1.55, 0.03 ) } );
	for ( const s of [ - 1, 1 ] ) add( sphere( 0.012, 6, 4 ), { color: 0x1a1512, rough: 0.2, matrix: mat4( s * 0.04, 1.58, 0.115 ) } );
	// straw hat
	add( cylinder( 0.1, 0.115, 0.1, 16 ), { ...HAT, matrix: mat4( 0, 1.7, 0.01 ) } );
	add( cylinder( 0.26, 0.25, 0.015, 24 ), { ...HAT, matrix: mat4( 0, 1.655, 0.01, - 0.05 ) } );
	add( cylinder( 0.118, 0.118, 0.025, 16 ), { color: 0x6b3a2a, rough: 0.8, matrix: mat4( 0, 1.67, 0.01 ) } );
	return mergePrepared( P );

}

import { ShaderModule, UniformBlock } from '../engine/gpu/Shader.js';
import { commonModule } from '../engine/render/wgsl/common.js';
import { SceneLighting } from './SceneLighting.js';

// Screen-space contact shadows for the sun: the fine shadows the cascaded maps miss (pebbles, shells,
// debris, grass, feet, rope, deck fittings). The scene is forward rendered, so the march reads the
// previous frame's opaque depth (SceneRenderer.opaqueCopy, still last frame's during the opaque
// pass) reprojected with last frame's view-projection. Per sunlit fragment within MAX_DIST: 8 steps
// toward the sun (4 beyond 12 m) over 0.3 m (near) .. 1 m (far), denser near the start, jittered per pixel and per
// frame (the TAAU resolves the noise), in two groups of independent loads with an early exit between. A sample occludes when it lies
// behind the depth buffer by more than a slope-scaled bias (no acne on flat ground) and less than a
// thickness that grows along the ray (no long false shadows behind thin or distant objects).
// Applied to the key light only, in the opaque pass only.
//
// Installed as the `contactShadow` lighting hook (fn hookContactShadow( P, N ) -> f32). Exclusions
// are per material define (the hook only sees defines): IS_WATER, NO_CONTACT_SHADOWS (set for
// `material.contactShadows = false` via ContactShadows.exclude( material ) and for every material
// under ContactShadows.skipRoots), and the late (transparent) pass (PASS_LATE: last frame's depth is
// this frame's there).
const GROUP = 4;
const GROUPS = 2;
const STEPS = GROUP * GROUPS;
const MAX_DIST = 32;
const NEAR_DIST = 12; // the second group of steps only runs nearer than this

const params = new UniformBlock( 'ContactShadowParams', { strength: [ 'f32', 1 ] }, { label: 'contactShadows' } );

// receivers under these objects are skipped (foliage: overdraw, still casts); adding a root marks
// the materials below it (call ContactShadows.refresh() after adding children to a root later)
class SkipSet extends Set {

	add( o ) {

		super.add( o );
		markTree( o );
		return this;

	}

}

function exclude( m ) {

	if ( m && m.setDefine ) m.setDefine( 'NO_CONTACT_SHADOWS', 1 );

}

function markTree( root ) {

	if ( root && root.traverse ) root.traverse( ( o ) => {

		if ( o.material ) for ( const m of Array.isArray( o.material ) ? o.material : [ o.material ] ) exclude( m );

	} );

}

export const ContactShadows = {
	strength: params.fields.strength,
	depthTexture: null,
	skipRoots: new SkipSet(),
	exclude,
	refresh() {

		for ( const r of this.skipRoots ) markTree( r );

	},
	module: null,
};

export function installContactShadows( { depthTexture, skip = [] } ) {

	ContactShadows.depthTexture = depthTexture;
	for ( const o of skip ) if ( o ) ContactShadows.skipRoots.add( o );
	const loop = [];
	for ( let g = 0; g < GROUPS; g ++ ) {

		let body = '';
		for ( let k = 0; k < GROUP; k ++ ) body += /* wgsl */`
			{
				let s = ( jit + ${ g * GROUP + k }.0 ) / ${ STEPS }.0;
				let u = s * s * 0.85 + s * 0.15; // denser near the contact
				let q = q0 + qd * u;
				let iw = 1.0 / q.w;
				let uv = q.xy * iw * vec2f( 0.5, -0.5 ) + 0.5;
				let d = textureLoad( contactDepth, vec2i( min( clamp( uv, vec2f( 0.0 ), vec2f( 1.0 ) ) * texSize, texSize - 1.0 ) ), 0 );
				let k2 = frame.near * iw * iw;
				let diff = d - q.z * iw; // > 0: the depth buffer is in front of the ray
				let thick = bias + 0.06 + u * len * 0.3;
				let occ = diff > bias * k2 && diff < thick * k2 && uv.x > 0.0 && uv.x < 1.0 && uv.y > 0.0 && uv.y < 1.0;
				hit = min( hit, select( 2.0, u, occ ) );
			}`;
		const go = g === 0 ? 'hit > 1.0' : `hit > 1.0 && w0 < ${ NEAR_DIST }.0`;
		loop.push( `\t\tif ( ${ go } ) {${ body }\n\t\t}` );

	}

	ContactShadows.module = new ShaderModule( {
		name: 'hook-contactShadow',
		deps: [ commonModule ],
		uniforms: params,
		uniformName: 'contactShadowParams',
		bindings: { contactDepth: { texture: () => ContactShadows.depthTexture } },
		code: /* wgsl */`
// 0 (occluded) .. 1 visibility of the key light
fn hookContactShadow( P: vec3f, N: vec3f ) -> f32 {
#if IS_WATER || NO_CONTACT_SHADOWS || PASS_LATE || PASS_DEPTH || PASS_COLOR
	return 1.0;
#else
	let L = frame.sunDir;
	let fwd = -vec3f( frame.view[ 0 ][ 2 ], frame.view[ 1 ][ 2 ], frame.view[ 2 ][ 2 ] );
	let w0 = dot( P - frame.cameraPos, fwd );
	// depth change per pixel on this surface (before any branch)
	let slope = max( abs( dpdx( w0 ) ), abs( dpdy( w0 ) ) );
	var vis = 1.0;
	let lit = dot( frame.sunColor, frame.sunColor ) > 1e-8 && dot( N, L ) > 0.02;
	if ( contactShadowParams.strength > 0.0 && w0 < ${ MAX_DIST }.0 && lit && P.y > frame.seaLevel - 0.3 ) {

		let texSize = vec2f( textureDimensions( contactDepth ) );
		let len = smoothstep( 2.0, 30.0, w0 ) * 0.7 + 0.3;
		let q0 = frame.prevViewProjNoJitter * vec4f( P, 1.0 );
		let qd = frame.prevViewProjNoJitter * vec4f( L * len, 0.0 );
		let bias = slope * 2.0 + w0 * 0.002 + 0.01;
		// screen coordinate of P (the hook has no fragment coordinate)
		let cc = frame.viewProj * vec4f( P, 1.0 );
		let pix = floor( ( cc.xy / cc.w * vec2f( 0.5, -0.5 ) + 0.5 ) * frame.resolution );
		let jit = fract( interleavedGradientNoise( pix ) + f32( frame.frameIndex ) * 0.618034 );
		var hit = 2.0; // ray parameter of the first occluded sample (> 1: none)
		// groups of independent loads (latency hiding), early exit between groups; far away the ray
		// covers few pixels and the first group is enough. Depths compare in reversed-Z device depth
		// (d ~ near / w): the bias and thickness in metres scale by near / w^2.
${ loop.join( '\n' ) }

		// the sun's penumbra is millimetres at this range: a hard shadow, faded out toward the end
		// of the ray (no cut-off line at its length)
		vis = select( 1.0, smoothstep( 0.55, 1.0, hit ), hit <= 1.0 );
		vis = 1.0 - ( 1.0 - vis ) * contactShadowParams.strength * smoothstep( ${ MAX_DIST }.0, ${ MAX_DIST - 8 }.0, w0 );

	}
	return vis;
#endif
}
`,
	} );
	SceneLighting.set( 'contactShadow', ContactShadows.module );

}

import { Vector3, Color, SRGBColorSpace } from '../engine/math/index.js';
import { Texture } from '../engine/gpu/Texture.js';
import { ShaderModule, UniformBlock } from '../engine/gpu/Shader.js';
import { ComputeKernel } from '../engine/gpu/Compute.js';
import { commonModule } from '../engine/render/wgsl/common.js';
import { G } from '../engine/render/Frame.js';
import { SceneLighting } from './SceneLighting.js';

// Sunlight bounced off the ground (one diffuse bounce, the dominant indirect light on a sunny beach):
// sunlit coral sand lights the underside of the pier, the eaves, the boat hull, palm trunks and the
// undersides of rocks and fronds.
//
// Bake (compute, only when the key light moves): a 512^2 map over the terrain domain (4 m texels,
// aligned with the terrain sun shadow map) of the light the ground reflects per unit of sun
// irradiance: albedo (sand / grass / forest / rock from the terrain masks, the sea as the seabed seen
// through the water column) x cos(sun, ground normal) x heightfield sun shadow, minus what the
// environment map's own ground (the atmosphere's dark planet surface) already gives, then blurred
// (binomial 5x5, ~4 m). Alpha: height of the bouncing surface (ground or sea level).
//
// Shading: irradiance = sun colour x cloud shadow x map(xz) x lower-hemisphere view factor of the
// normal ((1 - N.y) / 2) x fade with height above the bouncing surface, added to the indirect
// diffuse light (so the diffuse albedo, the material AO and the underwater tint all apply). One
// bilinear lookup via texel loads (no sampler) and only for normals that face down or sideways.
//
// Installed as the `bounce` lighting hook (fn hookBounce( P, N ) -> vec3f, irradiance / PI). Skipped for
// IS_WATER materials and materials with the define NO_GROUND_BOUNCE (the former
// `material.groundBounce = false`: GroundBounce.exclude( material )).
const N = 512;
// objects around the receiver shade part of the ground it sees (their shadows are not in the map)
const SURROUND = 0.6;
// the environment map's lower hemisphere: the atmosphere's planet ground (Atmosphere.groundAlbedo)
const ENV_GROUND = 0.08;

const params = new UniformBlock( 'GroundBounceParams', {
	sun: [ 'vec3f', new Vector3( 0, 1, 0 ) ],
	strength: [ 'f32', 1 ],
	ready: [ 'f32', 0 ],
}, { label: 'groundBounce' } );

export const GroundBounce = {
	strength: params.fields.strength,
	module: null,
	exclude( m ) {

		if ( m && m.setDefine ) m.setDefine( 'NO_GROUND_BOUNCE', 1 );

	},
};

const lin = ( r, g, b ) => {

	const c = new Color().setRGB( r, g, b, SRGBColorSpace );
	return `vec3f( ${ c.r.toFixed( 6 ) }, ${ c.g.toFixed( 6 ) }, ${ c.b.toFixed( 6 ) } )`;

};

// terrain: the TerrainGPU (its module: terrainHeightAt, terrainNormalRockLevel, terrainSplatLevel,
// terrainSunShadowAt); clouds: optional Clouds (its module: cloudsShadow)
export function installGroundBounce( { terrain, clouds = null } ) {

	const make = ( name ) => new Texture( { label: name, width: N, height: N, format: 'rgba16float', usage: [ 'sample', 'storage' ] } );
	const raw = make( 'groundBounceRaw' );
	const map = make( 'groundBounce' );
	const uSun = params.fields.sun;
	const uReady = params.fields.ready;

	const bakeRaw = new ComputeKernel( {
		label: 'Ground Bounce Bake',
		modules: [ commonModule, terrain.module ],
		bindings: { groundBounceParams: { uniform: params }, gbRawOut: { storageTexture: raw, access: 'write' } },
		workgroupSize: [ 8, 8, 1 ],
		code: /* wgsl */`
@compute @workgroup_size( WG_X, WG_Y, WG_Z )
fn main( @builtin( global_invocation_id ) gid: vec3u ) {
	let ij = vec2f( gid.xy );
	let xz = ( ij + 0.5 ) / ${ N }.0 * terrainParams.size + terrainParams.origin;
	let h = terrainHeightAt( xz );
	let nr = terrainNormalRockLevel( xz, 1.0 );
	let n = vec3f( nr.x, sqrt( sat( 1.0 - dot( nr.xy, nr.xy ) ) ), nr.y );
	let slope = 1.0 - n.y;
	let sp = terrainSplatLevel( xz, 1.0 );
	let L = groundBounceParams.sun;
	// land cover (same masks as the terrain material, coarsely)
	let rockW = sat( smoothstep( 0.35, 0.6, nr.z * 0.7 + smoothstep( 0.3, 0.62, slope ) * 0.5 ) );
	let sandW = smoothstep( 0.3, 0.72, sp.x ) * ( 1.0 - rockW );
	let jungleW = sat( smoothstep( 9.0, 24.0, h ) + smoothstep( 0.18, 0.36, slope ) );
	let veg = mix( ${ lin( 0.3, 0.36, 0.16 ) }, ${ lin( 0.12, 0.17, 0.07 ) }, jungleW );
	// dry coral sand, darker where damp near the water line
	let sand = ${ lin( 0.86, 0.79, 0.66 ) } * mix( 0.6, 1.0, smoothstep( 0.2, 1.2, h ) );
	let land = mix( mix( veg, sand, sandW ), vec3f( 0.08, 0.075, 0.065 ), rockW );
	// sea: the seabed (sand in the bay) seen through the water column, down and back up
	let depth = max( frame.seaLevel - h, 0.0 );
	let seabed = mix( ${ lin( 0.62, 0.58, 0.48 ) }, ${ lin( 0.25, 0.3, 0.22 ) }, smoothstep( 0.3, 0.7, sp.y ) );
	let sea = seabed * exp( ( frame.waterAbsorption + frame.waterScattering ) * depth * -2.4 ) * 0.9 + vec3f( 0.01, 0.025, 0.03 );
	let wet = smoothstep( 0.05, -0.1, h - frame.seaLevel );
	let albedo = mix( land, sea, wet );
	let nSurf = mix( n, vec3f( 0.0, 1.0, 0.0 ), wet );
	// heightfield sun shadow at the ground (same filtering as terrainSunShadowAt)
	let top = max( h, frame.seaLevel );
	let vis = terrainSunShadowAt( vec3f( xz.x, top, xz.y ) );
	let E = max( dot( nSurf, L ), 0.0 ) * vis * smoothstep( -0.02, 0.05, L.y );
	let o = max( albedo * E - ${ ENV_GROUND } * max( L.y, 0.0 ), vec3f( 0.0 ) );
	textureStore( gbRawOut, vec2u( gid.xy ), vec4f( o, top ) );
}
`,
	} );

	const w = [ 1, 4, 6, 4, 1 ];
	let taps = '';
	for ( let y = - 2; y <= 2; y ++ ) for ( let x = - 2; x <= 2; x ++ ) taps += `	sum += textureLoad( gbRaw, clamp( c + vec2i( ${ x }, ${ y } ), vec2i( 0 ), vec2i( ${ N - 1 } ) ), 0 ) * ${ ( w[ x + 2 ] * w[ y + 2 ] / 256 ).toFixed( 8 ) };\n`;
	const blur = new ComputeKernel( {
		label: 'Ground Bounce Blur',
		bindings: { gbRaw: { texture: raw, sampleType: 'unfilterable-float' }, gbMapOut: { storageTexture: map, access: 'write' } },
		workgroupSize: [ 8, 8, 1 ],
		code: /* wgsl */`
@compute @workgroup_size( WG_X, WG_Y, WG_Z )
fn main( @builtin( global_invocation_id ) gid: vec3u ) {
	let c = vec2i( gid.xy );
	var sum = vec4f( 0.0 );
${ taps }	textureStore( gbMapOut, vec2u( gid.xy ), sum );
}
`,
	} );

	// re-bake whenever the terrain's sun shadow is re-baked (the key light moved)
	const bake = () => {

		uSun.value.copy( G.sunDir.value );
		bakeRaw.dispatch( [ N / 8, N / 8, 1 ] );
		blur.dispatch( [ N / 8, N / 8, 1 ] );
		uReady.value = 1;

	};

	let done = false;
	const orig = terrain.updateSunShadow.bind( terrain );
	terrain.updateSunShadow = ( renderer, force = false ) => {

		const baked = orig( renderer, force );
		if ( baked || ! done ) bake( renderer );
		done = true;
		return baked;

	};

	const cloudCode = clouds && clouds.module
		// cloud shadow over the surroundings (the clouds module's bilinear shadow map lookup)
		? 'let cloud = cloudsShadow( P.xz );'
		: 'let cloud = 1.0;';

	GroundBounce.module = new ShaderModule( {
		name: 'hook-bounce',
		deps: [ commonModule, terrain.module, ...( clouds && clouds.module ? [ clouds.module ] : [] ) ],
		uniforms: params,
		uniformName: 'groundBounceParams',
		bindings: { groundBounceMap: { texture: map, sampleType: 'unfilterable-float' } },
		code: /* wgsl */`
fn hookBounce( P: vec3f, Nw: vec3f ) -> vec3f {
#if IS_WATER || NO_GROUND_BOUNCE
	return vec3f( 0.0 );
#else
	let view = sat( Nw.y * -0.5 + 0.5 );
	var E = vec3f( 0.0 );
	if ( view > 0.03 && P.y > frame.seaLevel - 0.3 && groundBounceParams.strength > 0.0 && groundBounceParams.ready > 0.0 ) {

		let st = clamp( terrainUvOf( P.xz ) * ${ N }.0 - 0.5, vec2f( 0.0 ), vec2f( ${ N }.0 - 1.001 ) );
		let i = vec2i( floor( st ) );
		let t = fract( st );
		let s = mix(
			mix( textureLoad( groundBounceMap, i, 0 ), textureLoad( groundBounceMap, i + vec2i( 1, 0 ), 0 ), t.x ),
			mix( textureLoad( groundBounceMap, i + vec2i( 0, 1 ), 0 ), textureLoad( groundBounceMap, i + vec2i( 1, 1 ), 0 ), t.x ),
			t.y
		);
		let above = P.y - s.w;
		// nothing from a surface above the receiver (under water: the sea surface is above), a
		// little less high up where more of the view is taken by other objects
		let fade = smoothstep( -0.3, 0.3, above ) * mix( 0.4, 1.0, smoothstep( 30.0, 4.0, above ) );
		${ cloudCode }
		// a face turned away from a low sun looks at the ground its object shades (a long shadow)
		let Lh = frame.sunDir.xz / max( length( frame.sunDir.xz ), 1e-3 );
		let selfShade = 1.0 - sat( -dot( Nw.xz, Lh ) ) * sat( 1.0 - frame.sunDir.y ) * 0.6;
		E = s.xyz * frame.sunColor * cloud * ( view * fade * selfShade * groundBounceParams.strength * ${ SURROUND } );

	}
	// the lighting adds hookBounce * diffuse colour: irradiance / PI (three: E * diffuse / PI)
	return E * INV_PI;
#endif
}
`,
	} );

	SceneLighting.set( 'bounce', GroundBounce.module );
	return { bake, map, raw };

}

import * as THREE from '../engine/index.js';
import { ShaderModule, UniformBlock } from '../engine/gpu/Shader.js';
import { commonModule } from '../engine/render/wgsl/common.js';
import { surfaceModule } from '../engine/render/wgsl/lighting.js';
import { G } from '../engine/render/Frame.js';
import { SceneLighting } from './SceneLighting.js';

// Local lights (lanterns, lamp posts, path lights, lit windows, the boat's cabin and navigation
// lights, the handheld flashlight) without a light object per lamp: unrolling every light into every
// material would multiply shader size and compile time. Instead the CPU picks the
// MAX lights nearest the camera each frame and packs them into three small uniform arrays; every
// lit material evaluates them in ONE loop (the physical BRDF: diffuse + GGX
// specular), inverse-square falloff with a smooth range window, optional spot cone, no shadows.
// Skipped entirely (uniform loop bound) when no light is active (daytime without the flashlight).
// They bypass the sun-only terms of the direct light (clouds, caustics, contact shadows).
//
// WGSL: `localLightsModule` (prefix localLights) installs the `localLights` lighting hook and exposes
//   uniforms localLights.{ pos[ 8 ], col[ 8 ], dir[ 8 ], count, flashOn, flashPos, flashDir, flashCol, flashCone }
//   fn localLightsSpotProfile( cd: f32, cosInner: f32, cosOuter: f32 ) -> f32
// for effects outside the lighting model (underwater beam in-scatter, marine snow: add the module).
// Exclusions per material define: IS_WATER, NO_LOCAL_LIGHTS (the former `material.localLights = false`);
// LOCAL_LIGHTS_CHEAP (material.localLightsCheap) = Lambert only.
const MAX = 8;
const v4 = () => Array.from( { length: MAX }, () => new THREE.Vector4() );
const params = new UniformBlock( 'LocalLightParams', {
	pos: [ `vec4f[${ MAX }]`, v4() ], // xyz, range^2
	col: [ `vec4f[${ MAX }]`, v4() ], // rgb x intensity, cos(inner cone)
	dir: [ `vec4f[${ MAX }]`, v4() ], // spot axis, cos(outer cone) (-2: point light)
	count: [ 'i32', 0 ],
	flashOn: [ 'f32', 0 ],
	flashCone: [ 'vec2f', new THREE.Vector2( 0.99, 0.82 ) ], // cos inner, cos outer
	flashPos: [ 'vec3f', new THREE.Vector3() ],
	flashDir: [ 'vec3f', new THREE.Vector3( 0, 0, - 1 ) ],
	flashCol: [ 'vec3f', new THREE.Vector3() ], // rgb x intensity
}, { label: 'localLights' } );
const F = params.fields;
const uPos = { array: F.pos.value };
const uCol = { array: F.col.value };
const uDir = { array: F.dir.value };
const uCount = F.count;

// the flashlight for effects outside the lighting model (underwater beam in-scatter, marine snow):
// `{ value }` handles of the localLights uniforms
export const FLASH = {
	on: F.flashOn,
	pos: F.flashPos,
	dir: F.flashDir,
	col: F.flashCol,
	cone: F.flashCone,
};

export const localLightsModule = new ShaderModule( {
	name: 'localLights',
	deps: [ commonModule, surfaceModule ],
	uniforms: params,
	uniformName: 'localLights',
	code: /* wgsl */`
// spot profile shared by the shading, the beam and the snow: hot centre, soft edge, faint spill
fn localLightsSpotProfile( cd: f32, cosInner: f32, cosOuter: f32 ) -> f32 {
	let m = smoothstep( cosOuter, cosInner, cd );
	return max( m * m, smoothstep( cosOuter - 0.55, cosOuter, cd ) * 0.05 );
}

fn hookLocalLights( s: Surface, P: vec3f, N: vec3f, V: vec3f, acc: ptr<function, LightAccum> ) {
#if !IS_WATER && !NO_LOCAL_LIGHTS
	let diffuseColor = s.albedo * ( 1.0 - s.metalness );
	let specF0 = mix( vec3f( 0.04 ) * s.specularIntensity, s.albedo, s.metalness );
	let specF90 = mix( s.specularIntensity, 1.0, s.metalness );
	let rough = clamp( s.roughness, 0.03, 1.0 );
	for ( var i = 0; i < localLights.count; i++ ) {
		let p = localLights.pos[ i ];
		let d = p.xyz - P;
		let d2 = dot( d, d );
		if ( d2 < p.w ) {
			let c = localLights.col[ i ];
			let sd = localLights.dir[ i ];
			let L = d * inverseSqrt( max( d2, 1e-6 ) );
			// smooth range window (1 - (d/r)^4)^2 on the inverse-square law
			let x = d2 / p.w;
			let win = sat( 1.0 - x * x );
			// spot: hot centre, soft edge at the outer cone, faint wide spill
			let spot = localLightsSpotProfile( dot( -L, sd.xyz ), c.w, sd.w );
			// Beer-Lambert over the underwater part of the path (straight, mean sea level): red dies
			// within metres, so what the torch lights far away under water is dim and blue-green
			let r = d2 * inverseSqrt( max( d2, 1e-6 ) );
			let under = sat( ( frame.seaLevel - min( P.y, p.y ) ) / max( abs( p.y - P.y ), 1e-3 ) );
			let Tw = exp( -( frame.waterAbsorption + frame.waterScattering ) * ( r * under ) );
			// the + 0.15 m^2 softens the near field of a lamp's finite size (no hot spot on the post)
			let lightColor = c.xyz * Tw * ( win * win * spot / ( d2 + 0.15 ) );
			let irradiance = max( dot( N, L ), 0.0 ) * lightColor;
#if LOCAL_LIGHTS_CHEAP
			// foliage (heavy overdraw): Lambert only
			( *acc ).directDiffuse += irradiance * diffuseColor * INV_PI;
#else
			( *acc ).directDiffuse += irradiance * diffuseColor * INV_PI;
			( *acc ).directSpecular += irradiance * BRDF_GGX( L, V, N, specF0, specF90, rough );
#if SHEEN
			( *acc ).directSpecular += irradiance * BRDF_Sheen( L, V, N, s.sheenColor, max( s.sheenRoughness, 0.07 ) );
#endif
#endif
		}
	}
#endif
}
`,
} );

SceneLighting.set( 'localLights', localLightsModule );

const _v = new THREE.Vector3(), _f = new THREE.Vector3(), _r = new THREE.Vector3(), _u = new THREE.Vector3();
const smooth = ( x, a, b ) => {

	const t = Math.min( 1, Math.max( 0, ( x - a ) / ( b - a ) ) );
	return t * t * ( 3 - 2 * t );

};

// CPU side: sources and the flashlight, packed every frame.
//   add( { position (live Vector3), color, intensity, range, dir?, cosInner?, cosOuter?, kind, flicker? } )
//   intensity: luminous intensity in scene units (illuminance at 1 m); range: cut-off distance (m)
export class LocalLights {

	constructor() {

		this.sources = [];
		this.enabled = true;
		this.strength = 1; // UI multiplier for the lamps (not the flashlight)
		this.flashlight = {
			on: false, intensity: 55, range: 30,
			color: new THREE.Color( 1.0, 0.71, 0.49 ), // ~4500 K
			cosInner: Math.cos( THREE.MathUtils.degToRad( 9 ) ), cosOuter: Math.cos( THREE.MathUtils.degToRad( 35 ) ),
			position: new THREE.Vector3(), dir: new THREE.Vector3( 0, 0, - 1 ), primed: false,
		};
		this._list = [];
		this.time = 0;
		this.active = 0;

	}

	add( src ) {

		src.phase = src.phase ?? Math.random() * 100;
		this.sources.push( src );
		return src;

	}

	toggleFlashlight( on = ! this.flashlight.on ) {

		this.flashlight.on = on;
		this.flashlight.primed = false;
		return on;

	}

	update( camera, dt ) {

		this.time += dt;
		let n = 0;
		FLASH.on.value = this.flashlight.on && this.enabled ? 1 : 0;
		const pos = uPos.array, col = uCol.array, dir = uDir.array;
		const fl = this.flashlight;
		if ( fl.on && this.enabled ) {

			// held a little right of and below the eye, lagging the view slightly
			camera.updateMatrixWorld();
			const e = camera.matrixWorld.elements;
			_r.set( e[ 0 ], e[ 1 ], e[ 2 ] ).normalize();
			_u.set( e[ 4 ], e[ 5 ], e[ 6 ] ).normalize();
			_f.set( - e[ 8 ], - e[ 9 ], - e[ 10 ] ).normalize();
			if ( ! fl.primed ) {

				fl.dir.copy( _f );
				fl.primed = true;

			}

			fl.dir.lerp( _f, 1 - Math.exp( - dt / 0.06 ) ).normalize();
			fl.position.setFromMatrixPosition( camera.matrixWorld ).addScaledVector( _r, 0.2 ).addScaledVector( _u, - 0.22 ).addScaledVector( _f, 0.15 );
			// faint against daylight (the scene's night is exposed far brighter than physical)
			const k = fl.intensity * ( 0.08 + 0.92 * smooth( G.night.value, 0.0, 0.6 ) );
			pos[ 0 ].set( fl.position.x, fl.position.y, fl.position.z, fl.range * fl.range );
			col[ 0 ].set( fl.color.r * k, fl.color.g * k, fl.color.b * k, fl.cosInner );
			dir[ 0 ].set( fl.dir.x, fl.dir.y, fl.dir.z, fl.cosOuter );
			n = 1;
			FLASH.pos.value.copy( fl.position );
			FLASH.dir.value.copy( fl.dir );
			FLASH.col.value.set( fl.color.r * k, fl.color.g * k, fl.color.b * k );
			FLASH.cone.value.set( fl.cosInner, fl.cosOuter );

		}

		// lamps: on from dusk (same ramp as the lantern glass), nearest first
		const on = smooth( G.night.value, 0.15, 0.75 ) * this.strength;
		if ( on > 0.002 && this.enabled ) {

			const cp = camera.position;
			const list = this._list;
			list.length = 0;
			for ( const s of this.sources ) {

				if ( s.enabled === false ) continue;
				if ( s.update ) s.update();
				s.d2 = s.position.distanceToSquared( cp );
				list.push( s );

			}

			list.sort( ( a, b ) => a.d2 - b.d2 );
			const slots = MAX - n;
			// fade out the farthest selected lights as they approach the cut (no popping)
			const dCut = list.length > slots ? Math.sqrt( list[ slots ].d2 ) : Infinity;
			for ( let i = 0; i < Math.min( slots, list.length ); i ++ ) {

				const s = list[ i ];
				const fade = Number.isFinite( dCut ) ? smooth( Math.sqrt( s.d2 ), dCut, dCut * 0.8 ) : 1;
				const fl2 = s.flicker ? 1 + s.flicker * Math.sin( this.time * 9 + s.phase ) * Math.sin( this.time * 5.3 + s.phase * 0.37 ) : 1;
				const k = s.intensity * on * fade * fl2 * ( s.scale ?? 1 );
				if ( k <= 1e-4 ) continue;
				const r = s.range;
				pos[ n ].set( s.position.x, s.position.y, s.position.z, r * r );
				col[ n ].set( s.color.r * k, s.color.g * k, s.color.b * k, s.cosInner ?? - 1.5 );
				if ( s.dir ) dir[ n ].set( s.dir.x, s.dir.y, s.dir.z, s.cosOuter ?? - 2 );
				else dir[ n ].set( 0, - 1, 0, - 2 );
				n ++;

			}

		}

		uCount.value = n;
		this.active = n;

	}

}

// Boat lights in the hull frame: warm cabin dome, instrument glow, navigation lights (red port,
// green starboard, white masthead and stern). Positions follow the boat's world matrix.
export function addBoatLights( lights, boat ) {

	const L = boat.lines;
	const obj = boat.group;
	const sternY = L.sheerY( 0 ) + 0.1;
	const defs = [
		{ p: [ 0, 2.24, 0.42 ], color: [ 1.0, 0.84, 0.62 ], intensity: 0.9, range: 5.5, kind: 'boatDome' },
		{ p: [ - 0.45, 1.5, 1.12 ], color: [ 0.45, 0.75, 1.0 ], intensity: 0.12, range: 2.2, kind: 'boatInstruments' },
		{ p: [ 0.47, 3.45, - 0.47 ], color: [ 1.0, 0.06, 0.03 ], intensity: 1.4, range: 8, kind: 'boatNav', side: [ 1, 0, 0 ] },
		{ p: [ - 0.47, 3.45, - 0.47 ], color: [ 0.05, 1.0, 0.3 ], intensity: 1.4, range: 8, kind: 'boatNav', side: [ - 1, 0, 0 ] },
		{ p: [ 0, 3.97, - 0.5 ], color: [ 1.0, 0.95, 0.85 ], intensity: 1.2, range: 8, kind: 'boatNav' },
		{ p: [ 0, sternY, L.zAft - 0.05 ], color: [ 1.0, 0.95, 0.85 ], intensity: 0.8, range: 7, kind: 'boatNav' },
	];
	const out = [];
	for ( const d of defs ) {

		const local = new THREE.Vector3( ...d.p );
		const localDir = d.side ? new THREE.Vector3( ...d.side ) : null;
		const src = {
			position: new THREE.Vector3(), color: new THREE.Color( ...d.color ), intensity: d.intensity, range: d.range, kind: d.kind,
			dir: localDir ? new THREE.Vector3() : null, cosInner: localDir ? 0.25 : undefined, cosOuter: localDir ? - 0.2 : undefined,
			update() {

				obj.updateWorldMatrix( true, false );
				this.position.copy( local ).applyMatrix4( obj.matrixWorld );
				if ( localDir ) this.dir.copy( localDir ).transformDirection( obj.matrixWorld );

			},
		};
		src.update();
		out.push( lights.add( src ) );

	}

	return out;

}

// Village lights (Village.getLightSources()): lanterns, lamp posts, path lights, lit windows. Window
// lights sit just outside the pane and only light outward (porches); lanterns flicker a little.
export function addVillageLights( lights, village ) {

	const K = { lantern: 1.5, pathLight: 1.0, window: 0.8 };
	const R = { lantern: 11, pathLight: 7, window: 6 };
	for ( const l of village.getLightSources() ) {

		const kind = l.kind || 'lantern';
		const src = { position: l.position, color: l.color, intensity: l.intensity * ( K[ kind ] ?? 1.2 ), range: R[ kind ] ?? 12, kind };
		if ( kind === 'window' ) {

			// outward normal: away from the nearest building centre
			let best = null, bd = Infinity;
			for ( const b of village.buildings || [] ) {

				const dd = ( b.x - l.position.x ) ** 2 + ( b.z - l.position.z ) ** 2;
				if ( dd < bd ) {

					bd = dd;
					best = b;

				}

			}

			const n = best ? _v.set( l.position.x - best.x, 0, l.position.z - best.z ) : _v.set( 0, 0, 1 );
			if ( n.lengthSq() < 1e-6 ) n.set( 0, 0, 1 );
			n.normalize();
			src.position = l.position.clone().addScaledVector( n, 0.35 );
			src.dir = n.clone();
			src.cosInner = 0.35;
			src.cosOuter = - 0.15;

		} else {

			src.flicker = 0.08;

		}

		lights.add( src );

	}

}

import { ShaderModule } from '../engine/gpu/Shader.js';

// Screen-door cross-fade between levels of detail (and for anything that appears or disappears
// with distance), so nothing switches over in one frame.
//
// Both levels are drawn during a transition band. Each discards the pixels where the ordered-dither
// (Bayer 4x4) threshold says it isn't visible: the incoming level keeps the pixels below `fade`,
// the outgoing one the pixels at or above the SAME threshold, so together they cover every pixel
// exactly once (no holes, no double-drawn pixels). The pattern shifts every frame, so the TAA
// resolves the 16 dither levels into a smooth blend.
//
// fade: 0..1, the share of this level that is visible (the same value for both levels of one
// instance: ramp it with distance across the band on the CPU or in the vertex stage).
//
// WGSL (lodFadeModule):
//   fn bayer4( pixel: vec2f ) -> f32                 threshold in (0, 1) for a fragment coordinate
//   fn lodFadeVisible( pixel: vec2f, fade: f32, outgoing: bool ) -> bool
// In a surface / shadow snippet: `if ( ! lodFadeVisible( in.pixel, fade, false ) ) { discard; }`
// (Nothing is discarded at fade >= 1 (incoming) or fade <= 0 (outgoing).)

export const lodFadeModule = new ShaderModule( {
	name: 'lodFade',
	code: /* wgsl */`
// Bayer 4x4 threshold in (0, 1): bit-interleaved formula of
//   0  8  2 10 / 12  4 14  6 / 3 11  1  9 / 15  7 13  5
fn bayer4( pixel: vec2f ) -> f32 {
	let f = frame.frameIndex;
	// shift the pattern by a different offset every frame (all 16 over 16 frames)
	let p = vec2u( pixel ) + vec2u( f * 3u, ( f >> 2u ) * 1u );
	let x0 = p.x & 1u; let x1 = ( p.x >> 1u ) & 1u;
	let y0 = p.y & 1u; let y1 = ( p.y >> 1u ) & 1u;
	let v = ( ( x0 ^ y0 ) << 3u ) | ( y0 << 2u ) | ( ( x1 ^ y1 ) << 1u ) | y1;
	return ( f32( v ) + 0.5 ) / 16.0;
}

fn lodFadeVisible( pixel: vec2f, fade: f32, outgoing: bool ) -> bool {
	let t = bayer4( pixel );
	return select( ( t < fade ), ( t >= fade ), outgoing );
}
`,
} );

// Fade factor across a distance band [start, end] (0 before, 1 after), for the level that takes over
// at `end`. Use on the CPU when bucketing instances.
export function bandFade( dist, start, end ) {

	const t = ( dist - start ) / Math.max( end - start, 1e-6 );
	return t <= 0 ? 0 : t >= 1 ? 1 : t * t * ( 3 - 2 * t );

}

import { Material } from '../engine/render/Material.js';
import { Color } from '../engine/math/index.js';

// All world objects use these material classes so they share underwater lighting
// (caustics, water-column attenuation, tinted ambient) and wetness handling: in the engine every
// lit Material goes through the scene lighting (render/wgsl/lighting.js) and its hooks, so these
// are thin wrappers over the engine's Material that keep the three.js-style option names working
// (color, roughness, metalness, emissive, emissiveIntensity, opacity, transparent, side (THREE
// numeric FrontSide / BackSide / DoubleSide or 'front' / 'back' / 'double'), alphaTest,
// depthWrite, vertexColors, envMapIntensity, and for physical(): clearcoat, clearcoatRoughness,
// specularIntensity, sheen, sheenColor, sheenRoughness, ior).
//
// The TSL node slots (colorNode, roughnessNode, normalNode, positionNode, ...) are WGSL snippets
// now: `vertex`, `surface`, `output` (see engine/render/Material.js). They can be passed in the
// params or assigned afterwards (then set `needsUpdate = true` if the material was drawn already).
// The physical parameters seed the Surface before the material's own `surface` snippet runs.

const SIDES = { 0: 'front', 1: 'back', 2: 'double', front: 'front', back: 'back', double: 'double' };

function engineParams( params ) {

	const o = { ...params };
	if ( o.side !== undefined ) o.side = SIDES[ o.side ] || 'front';
	return o;

}

export class SceneMaterial extends Material {

	constructor( params = {}, physicalFields = null ) {

		const o = engineParams( params );
		const uniforms = { ...( o.uniforms || {} ) };
		uniforms.envMapIntensity = [ 'f32', o.envMapIntensity ?? 1 ];
		uniforms.emissiveIntensity = [ 'f32', o.emissiveIntensity ?? 1 ];
		if ( physicalFields ) Object.assign( uniforms, physicalFields );
		super( { ...o, uniforms } );
		this.isSceneMaterial = true;
		this.isMeshStandardMaterial = true;

	}

	// numeric (three) or string sides
	get side() { return this._side; }
	set side( v ) {

		const s = SIDES[ v ] || 'front';
		if ( s !== this._side && this._side !== undefined ) this.version ++;
		this._side = s;

	}

	get emissiveIntensity() { return this.uniforms.emissiveIntensity.value; }
	set emissiveIntensity( v ) { this.uniforms.emissiveIntensity.value = v; }
	get envMapIntensity() { return this.uniforms.envMapIntensity.value; }
	set envMapIntensity( v ) { this.uniforms.envMapIntensity.value = v; }

	// the material's own surface snippet runs after the parameter seeding
	get surface() {

		return this._prelude() + ( this._surface || '' );

	}

	set surface( v ) {

		this._surface = v;

	}

	_prelude() {

		return '\ts.emissive = s.emissive * mat.emissiveIntensity;\n\ts.envIntensity = mat.envMapIntensity;\n';

	}

}

export class ScenePhysicalMaterial extends SceneMaterial {

	constructor( params = {} ) {

		const clearcoat = params.clearcoat ?? 0;
		const sheen = params.sheen ?? 0;
		super( params, {
			clearcoat: [ 'f32', clearcoat ],
			clearcoatRoughness: [ 'f32', params.clearcoatRoughness ?? 0 ],
			specularIntensity: [ 'f32', params.specularIntensity ?? 1 ],
			sheen: [ 'f32', sheen ],
			sheenColor: [ 'vec3f', null ],
			sheenRoughness: [ 'f32', params.sheenRoughness ?? 1 ],
			ior: [ 'f32', params.ior ?? 1.5 ],
		} );
		this.isMeshPhysicalMaterial = true;
		if ( params.sheenColor !== undefined ) this.uniforms.sheenColor.value = toColor( params.sheenColor );
		else this.uniforms.sheenColor.value = toColor( 0x000000 );
		// three switches the lobes on when the parameter is > 0 at build time
		if ( clearcoat > 0 ) this.defines.CLEARCOAT = 1;
		if ( sheen > 0 ) this.defines.SHEEN = 1;

	}

	get clearcoat() { return this.uniforms.clearcoat.value; }
	set clearcoat( v ) {

		if ( ( v > 0 ) !== !! this.defines.CLEARCOAT ) this.setDefine( 'CLEARCOAT', v > 0 ? 1 : 0 );
		this.uniforms.clearcoat.value = v;

	}

	get clearcoatRoughness() { return this.uniforms.clearcoatRoughness.value; }
	set clearcoatRoughness( v ) { this.uniforms.clearcoatRoughness.value = v; }
	get specularIntensity() { return this.uniforms.specularIntensity.value; }
	set specularIntensity( v ) { this.uniforms.specularIntensity.value = v; }
	get sheen() { return this.uniforms.sheen.value; }
	set sheen( v ) {

		if ( ( v > 0 ) !== !! this.defines.SHEEN ) this.setDefine( 'SHEEN', v > 0 ? 1 : 0 );
		this.uniforms.sheen.value = v;

	}

	get sheenColor() { return this.uniforms.sheenColor.value; }
	get sheenRoughness() { return this.uniforms.sheenRoughness.value; }
	set sheenRoughness( v ) { this.uniforms.sheenRoughness.value = v; }
	get ior() { return this.uniforms.ior.value; }
	set ior( v ) { this.uniforms.ior.value = v; }

	_prelude() {

		return super._prelude() + `\ts.clearcoat = mat.clearcoat;
	s.clearcoatRoughness = mat.clearcoatRoughness;
	s.specularIntensity = mat.specularIntensity;
	s.sheenColor = mat.sheenColor * mat.sheen;
	s.sheenRoughness = mat.sheenRoughness;
	s.ior = mat.ior;
`;

	}

}

function toColor( v ) {

	return v && v.isColor ? v.clone() : new Color().set( v );

}

