const SHORE_SIM_RES: f32 = ${ res }.0;
const SHORE_SIM_LACE_TILE: f32 = ${ LACE_TILE };

fn shoreSimUvOf( xz: vec2f ) -> vec2f {
	return ( xz - shoreSimP.min ) / shoreSimP.size;
}

fn shoreSimInside( uv: vec2f ) -> f32 {
	return smoothstep( 0.0, 0.02, uv.x ) * smoothstep( 1.0, 0.98, uv.x ) * smoothstep( 0.0, 0.02, uv.y ) * smoothstep( 1.0, 0.98, uv.y );
}

// bilinear state at texture coordinate uv, from 4 loads
fn shoreSimStateAt( uv: vec2f ) -> vec4f {
	let fp = clamp( uv * SHORE_SIM_RES - 0.5, vec2f( 0.0 ), vec2f( SHORE_SIM_RES - 1.001 ) );
	let i = vec2i( floor( fp ) );
	let t = fract( fp );
	let a = textureLoad( shoreSimStateTex, i, 0 );
	let b = textureLoad( shoreSimStateTex, i + vec2i( 1, 0 ), 0 );
	let c = textureLoad( shoreSimStateTex, i + vec2i( 0, 1 ), 0 );
	let d = textureLoad( shoreSimStateTex, i + vec2i( 1, 1 ), 0 );
	return mix( mix( a, b, t.x ), mix( c, d, t.x ), t.y );
}

// raw state (foam, wetness, residue amount, lace offset), faded out at the region border
fn shoreSimState( xz: vec2f ) -> vec4f {
	let uv = shoreSimUvOf( xz );
	var out = vec4f( 0.0 );
	if ( uv.x > 0.0 && uv.x < 1.0 && uv.y > 0.0 && uv.y < 1.0 ) {
		out = shoreSimStateAt( uv ) * shoreSimInside( uv );
	}
	return out;
}

// vec4( foam amount on the water, sand wetness, foam amount left on the sand, flow speed ).
// Used by the water (x, w), the underwater lighting (x) and the terrain (y, z; for the lacy look
// of the foam left on the sand use shoreSimSandFoam()). No sampler bindings.
fn shoreSimSample( xz: vec2f ) -> vec4f {
	return shoreSimState( xz );
}

// bilinear lace lookup from 4 loads of the nearest-filtered copy (no sampler binding needed)
fn shoreSimLaceLoad( q: vec2f ) -> vec4f {
	let fp = q / SHORE_SIM_LACE_TILE * ${ laceN }.0 - 0.5;
	let i = vec2i( floor( fp ) );
	let t = fract( fp );
	let m = vec2i( ${ laceN - 1 } );
	let a = textureLoad( shoreSimLaceNearest, i & m, 0 );
	let b = textureLoad( shoreSimLaceNearest, ( i + vec2i( 1, 0 ) ) & m, 0 );
	let c = textureLoad( shoreSimLaceNearest, ( i + vec2i( 0, 1 ) ) & m, 0 );
	let d = textureLoad( shoreSimLaceNearest, ( i + vec2i( 1, 1 ) ) & m, 0 );
	return mix( mix( a, b, t.x ), mix( c, d, t.x ), t.y );
}

// Foam left on the sand (0..1): thin bubble lines and single bubbles where the draining water
// left its foam, popping patch by patch as it dries. Static on the sand (world space). s:
// shoreSimSample( xz ). (h: the ground height at xz, unused.)
fn shoreSimSandFoam( xz: vec2f, s: vec4f, h: f32 ) -> f32 {
	let r = s.z;
	// (screen-space footprint first: derivatives before the branch)
	let fp = length( fwidth( xz ) ) / SHORE_SIM_LACE_TILE * ${ laceN }.0;
	var out = 0.0;
	if ( r > 0.01 ) {
		let lace = shoreSimLaceLoad( xz + 11.3 );
		// fade to the average where a pixel covers several strands (no mipmaps on the load path)
		let near = smoothstep( 3.0, 1.2, fp );
		let keep = smoothstep( lace.w * 0.55, lace.w * 0.55 + 0.08, r ); // staggered popping
		// thin bubble lines where the strands were, a little wider where more foam was left
		let lw = r * 0.1 + 0.06;
		let strand = ( 1.0 - smoothstep( lw, lw + 0.07, lace.x ) ) * ( lace.z * 0.5 + 0.6 );
		let lines = max( strand * smoothstep( 0.02, 0.25, r ) * keep, lace.y * keep * 0.8 );
		out = mix( smoothstep( 0.08, 0.6, r ) * 0.12, lines, near ) * 0.85;
	}
	return out;
}
`,
		} );

		// Deposit foam where spray falls back (compute): n drops at world xz
		this.depositModule = new ShaderModule( {
			name: 'shoreSimDeposit',
			deps: [ this.module ],
			bindings: { shoreSimDepositA: { storage: this.deposit, access: 'read_write', type: 'atomic<u32>' } },
			code: /* wgsl */`
fn shoreSimDepositAt( xz: vec2f, n: u32 ) {
	let uv = shoreSimUvOf( xz );
	if ( uv.x > 0.0 && uv.x < 1.0 && uv.y > 0.0 && uv.y < 1.0 ) {
		let ij = vec2u( uv * SHORE_SIM_RES );
		atomicAdd( &shoreSimDepositA[ ij.y * ${ res }u + ij.x ], n );
	}
}
`,
		} );

		this.kernel = new ComputeKernel( {
			label: 'Shore Sim',
			modules: [ this.module, shore.module, terrainGPU.module ],
			workgroupSize: [ 8, 8, 1 ],
			bindings: {
				shoreSimOut: { storageTexture: this.stateB, access: 'write' },
				shoreSimDeposit: { storage: this.deposit, access: 'read_write', type: 'u32' },
				shoreSimLace: { texture: this.lace },
			},
			code: /* wgsl */`
@compute @workgroup_size( WG_X, WG_Y, WG_Z )
fn main( @builtin( global_invocation_id ) gid: vec3u ) {
	if ( gid.x >= ${ res }u || gid.y >= ${ res }u ) { return; }
	let ij = vec2f( gid.xy );
	let uv = ( ij + 0.5 ) / SHORE_SIM_RES;
	let p = shoreSimP.min + uv * shoreSimP.size;
	let ground = terrainHeightAt( p );
	let depth = frame.seaLevel - ground;
	let dt = frame.dt;

	let here = textureLoad( shoreSimStateTex, vec2i( gid.xy ), 0 );
	let di = gid.y * ${ res }u + gid.x;
	let drops = f32( shoreSimDeposit[ di ] );
	if ( drops > 0.0 ) {
		shoreSimDeposit[ di ] = 0u;
	}

	// far from the surf and swash zone nothing happens: just let everything decay
	if ( depth > 7.0 || ground > 3.2 ) {
		let k = exp( - dt / 2.0 );
		textureStore( shoreSimOut, gid.xy, vec4f( here.x * k, here.y * exp( - dt / shoreSimP.dryTime ), here.z * k, 0.0 ) );
		return;
	}

	let sw = shoreEvaluateWorld( p, depth, ground );

	// fraction of this texel covered by water: open water, or the swash sheet up to its leading
	// edge (soft over one texel, so no field stored here shows the texel grid)
	let cov = select( sat( ( sw.runup - sw.inland ) / ( shoreSimP.size / SHORE_SIM_RES ) + 0.5 ), 1.0, depth > 0.03 );
	let covered = cov > 0.5;
	let vel = select( vec2f( 0.0 ), sw.flow, covered );

	// semi-Lagrangian advection (backtrace)
	let back = uv - vel * dt / shoreSimP.size;
	let prev = shoreSimStateAt( back );

	// foam: made where the bore roller / plunge point / swash front pass, torn into patches by
	// the mottling of the lace texture, then it decays (bubbles rising and popping) and drains
	// into the sand once the water has gone
	let mott = textureSampleLevel( shoreSimLace, smpLinearRepeat, p / ( SHORE_SIM_LACE_TILE * 4.3 ), 2.0 ).z;
	let patchK = smoothstep( 0.25, 0.75, mott ) * 0.8 + 0.35;
	let swashy = smoothstep( 0.35, 0.05, depth );
	// dense foam collapses within a second or two (big bubbles burst first), the lace it leaves lingers
	let lace = mix( shoreSimP.surfFoamLife, shoreSimP.foamLife, swashy );
	let life = mix( 0.7, mix( lace, 0.8, smoothstep( 0.3, 0.8, prev.x ) ), cov );
	let gen = ( sw.foam * 2.2 + sw.swashFoam * 1.4 ) * patchK * cov;
	// the foam is diluted where the flow spreads it out (the uprush thinning as it climbs, the
	// backwash draining): d(foam)/dt = - foam * du/ds along the flow
	let h = shoreSimP.size / SHORE_SIM_RES;
	let dirH = sw.dir * ( h / shoreSimP.size );
	let uAhead = shoreSimStateAt( uv + dirH ).w;
	let uBehind = shoreSimStateAt( uv - dirH ).w;
	let spreadRate = max( ( uAhead - uBehind ) / ( 2.0 * h ), 0.0 );
	let splash = drops * shoreSimP.depositGain * cov;
	let foam = min( prev.x * exp( - dt * ( 1.0 / life + spreadRate ) ) + gen * shoreSimP.foamGen * dt + splash, 1.0 );

	// wetness: saturated while covered, then dries
	let wet = max( here.y * exp( - dt / shoreSimP.dryTime ), cov );

	// residue: foam stranded on the sand when the water leaves (the draining film gathers its
	// bubbles into lines, so it concentrates); washed away by the next uprush
	let stranded = min( here.x * 2.4, 1.0 ) * ( 1.0 - cov );
	let residue = max( here.z * mix( exp( - dt / shoreSimP.residueLife ), 0.85, cov ), stranded );

	textureStore( shoreSimOut, gid.xy, vec4f( foam, wet, residue, dot( vel, sw.dir ) ) );
}
`,
		} );

	}

	update() {

		this.kernel.dispatch( this.kernel.groups( this.res, this.res ) );
		const size = { width: this.res, height: this.res };
		GPU.getEncoder().copyTextureToTexture( { texture: this.stateB.getGPU() }, { texture: this.stateA.getGPU() }, size );

	}

}

import { Vector2 } from '../engine/math/index.js';
import { Texture, UniformBlock, ShaderModule, commonModule } from '../engine/webgpu.js';
import { G, GRAVITY } from '../engine/render/Frame.js';

// Depth-aware shoreline waves.
//
// Wave phase comes from the precomputed travel-time field (refraction around headlands, fronts
// aligning with depth contours). Each individual wave m has its own height (sets + along-shore
// variation). Height grows in shallow water (Green's law) until H > gamma * depth. The wave then
// plunges: the front face turns into a vertical, concave wall under the crest (the thrown lip is a
// separate sheet, see Breakers), the tube collapses where the lip lands and the wave continues
// as a turbulent bore, which finally runs up the beach as a thin swash sheet whose leading edge
// advances and retreats (vertical run-up R(t) compared against the sand height).

// WGSL (this.module, prefix shore). Every function below is a real WGSL function (not inlined at
// every call site): keeps the vertex, simulation and query shaders small (compile times).
//   struct ShoreSample { disp, nShore, env, foam, breaking, u, dir, exposure, swashLevel, swashCovered (0/1),
//                        thick, swashFoam, runup, inland, dRdt, tau, flow, flowSpeed, face, roller }
//   fn shoreEvaluate( xz: vec2f, depth: f32, groundH: f32 ) -> ShoreSample          (with the normal: the water mesh)
//   fn shoreEvaluateNoNormal( xz, depth, groundH ) -> ShoreSample                    (no normal: queries)
//   fn shoreEvaluateWorld( xz, depth, groundH ) -> ShoreSample                       (a fixed world point: ShoreSim)
//   struct ShorePhase { sh: vec4f, T: f32, dir: vec2f, exposure: f32, along: f32, s: f32 }
//   fn shorePhaseAt( xz: vec2f ) -> ShorePhase
//   fn shoreWaveAmp( m: f32, along: f32 ) -> f32
//   fn shoreShape( u, A, d, lam ) -> vec4f                     ( x, y, foam, b )
//   fn shoreCrest( A, d ) -> vec4f                             ( b, H, trough, lipThrow )   (crestParams)
//   fn shoreBore( A, d ) -> vec4f                              ( Hb, Wt, Xc, wBore )        (boreParams)
//   fn shoreBreakDepth( xz, dir, u, lam, d ) -> f32
//   fn shoreDirAt( xz: vec2f ) -> vec3f                        ( dir.x, dir.z, exposure ) (buildDirTexture)
//   struct ShoreMedium { scatter: vec3f, absorb: vec3f };  fn shoreSurfMedium( xz, depth ) -> ShoreMedium
//   fn shoreCrestPath( lagXZ: vec2f, depth: f32, Tv: vec3f ) -> f32
//   fn shoreSwashClip( xz: vec2f, thickness: f32 ) -> f32
//   fn shoreSwashEdge( xz: vec2f, thickness: f32 ) -> vec4f   ( clipped thickness, distance to the
//        swash front (m, > 0 on the water side; 1e3 away from the swash), tau, run-up Rt )
// Consumes terrainHeightAt( xz ) and terrainShoreSample( xz ) from the terrain module.

const TAU = Math.PI * 2;
const BEACH_SLOPE = 0.066; // run-up is converted to a horizontal excursion with this slope
const SWASH_UP = 0.4, SWASH_DOWN = 0.55; // fractions of the period: uprush, backwash
const SWASH_OVERSHOOT = 1.2; // the mesh sheet reaches this far (m) past the leading edge (> the mesh spacing,
// so the per-pixel front, not the triangles, always decides where the sheet ends)

const f = ( x ) => {

	const s = String( x );
	return s.includes( '.' ) || s.includes( 'e' ) ? s : s + '.0';

};

// one evaluate() variant: mode 'normal' (the water mesh), 'plain' (withNormal: false), 'world'
function evaluateCode( name, mode ) {

	return /* wgsl */`
fn ${ name }( xz: vec2f, depth: f32, groundH: f32 ) -> ShoreSample {
	let ph = shorePhaseAt( xz );
	let sh = ph.sh;
	let exposure = ph.exposure;
	let along = ph.along;
	let dir = ph.dir;
	let Tp = shoreP.period;

	let d = depth;
	let c = sqrt( clamp( d, 0.3, 25.0 ) * SHORE_GRAVITY );
	let lam = c * Tp;

	let s = ph.s;
	let m = floor( s + 0.5 );
	let u = s - m;

	// wave height with smooth hand-over between consecutive waves at the trough
	let A0 = shoreWaveAmp( m, along );
	let An = shoreWaveAmp( m + sign( u ), along );
	let A = mix( A0, An, smoothstep( 0.32, 0.5, abs( u ) ) * 0.5 );
	// the breaking state of the whole wave comes from the depth under its crest
	let dB = shoreBreakDepth( xz, dir, u, lam, d );

	// offshore fade-in (FFT covers deep water) and fade on land (the swash sheet takes over there)
	let env = smoothstep( 26.0, 13.0, d ) * smoothstep( -0.25, 0.05, d ) * sat( exposure * 1.4 ) * shoreP.enabled;

	// finite difference along the propagation direction for the normal
	let e = 0.15;
	var face = 0.0;
	var roller = 0.0;
${ mode === 'world' ? `	let r = shoreWorld( u, A, dB, lam, env );
	let s0 = vec4f( r.z, r.y, r.x, r.w );` : mode === 'normal' ? `	let pair = shoreShapePair( u, - e / lam, A, dB, lam );
	let s0 = pair.s0;
	let s1 = pair.s1;
	face = s1.z * env;
	roller = s1.w * env;` : `	let s0 = shoreShape( u, A, dB, lam );` }

	var disp = vec3f( dir.x * s0.x, s0.y, dir.y * s0.x ) * env;

	var nShore = vec3f( 0.0, 1.0, 0.0 );
${ mode === 'normal' ? `	{
		let dX = e + ( s1.x - s0.x ) * env;
		let dY = ( s1.y - s0.y ) * env;
		let tAlong = vec3f( dir.x * dX, dY, dir.y * dX );
		let tAcross = vec3f( - dir.y, 0.0, dir.x );
		// epsilon: never a zero vector; never facing down (the mesh doesn't overhang, the lip sheet does)
		let n = normalize( cross( tAcross, tAlong ) + vec3f( 0.0, 1e-4, 0.0 ) );

		// the whitewater roller is not a smooth tube: lumps of foam tumble along its front and over
		// its top (relief of a few decimetres, with its slope in the normal). Noise, not a sum of sines:
		// regular bumps along the crest read as a row of identical puffs. Bigger, fewer lumps in some
		// stretches, a lower, smoother churn in others (different for every wave).
		let sx = u * lam; // rest position along the wave direction (m, seaward)
		let t = frame.time;
		let mW = floor( ph.s + 0.5 );
		let lumpy = sat( perlin2( vec2f( along * 0.045, mW * 3.7 ) ) * 1.2 + 0.55 );
		let amp = roller * mix( 0.25, 0.7, lumpy );
		let q1 = vec2f( along * 0.28, sx * 0.7 - t * 0.8 );
		let q2 = vec2f( along * 0.8 + 11.3, sx * 1.6 - t * 1.5 );
		let eL = 0.25;
		let L0 = perlin2( q1 ) * 0.7 + perlin2( q2 ) * 0.3;
		let La = perlin2( q1 + vec2f( eL * 0.28, 0.0 ) ) * 0.7 + perlin2( q2 + vec2f( eL * 0.8, 0.0 ) ) * 0.3;
		let Ls = perlin2( q1 + vec2f( 0.0, eL * 0.7 ) ) * 0.7 + perlin2( q2 + vec2f( 0.0, eL * 1.6 ) ) * 0.3;
		// lumps stand up from the roller (rounded caps, flatter troughs between them)
		let lump = max( L0 * 1.5 + 0.2, -0.3 );
		disp.y += lump * amp;
		let dAlong = select( 0.0, ( La - L0 ) / eL * 1.5, L0 * 1.5 + 0.2 > -0.3 );
		let dSx = select( 0.0, ( Ls - L0 ) / eL * 1.5, L0 * 1.5 + 0.2 > -0.3 );
		let dShore = - dSx; // d/d(shoreward) = - d/dsx
		let g = ( vec2f( - dir.y, dir.x ) * dAlong + dir * dShore ) * amp * n.y;
		nShore = normalize( vec3f( n.x - g.x, max( n.y, 0.04 ), n.z - g.y ) );
	}` : '' }

	// ---- swash: run-up of the most recent wave on the sand
	let swr = shoreSwashRunup( sh, along, groundH );
	let front = swr.Rt - swr.inland; // signed distance to the leading edge (m), > 0 under the sheet
	let covered = front > 0.0;
	// leading edge velocity along the slope (m/s), positive = uphill
	let dRdt = select( pow( max( swr.sb, 1e-3 ), 0.6 ) * ( - 1.6 / SHORE_SWASH_DOWN ), pow( 1.0 - swr.su, 0.5 ) * ( 1.5 / SHORE_SWASH_UP ), swr.isUp ) * swr.RhMax / Tp;
	// thin sheet (a few cm, thickening behind the leading edge). The mesh sheet overshoots the
	// leading edge a little; the water shader cuts it exactly on the front (swashClip), so the edge
	// doesn't follow the mesh triangles.
	let fm = front + SHORE_SWASH_OVERSHOOT;
	let thick = clamp( min( fm * 0.3, max( fm - 0.1, 0.0 ) * ( SHORE_BEACH_SLOPE * 0.22 ) + 0.03 ), -0.1, 0.12 );
	let swashLevel = groundH + thick;
	// bubbly foam line riding the leading edge all the way up (left behind as the swash mark)
	let uprush = smoothstep( 0.46, 0.32, swr.tau );
	let edge = smoothstep( 0.8, 0.0, front ) * smoothstep( -0.05, 0.05, front ) * uprush * smoothstep( 0.0, 1.0, swr.Rt );
	let swashFoam = edge * 0.9;

	// ---- depth-averaged water velocity (along dir), for foam advection
	// waves / bores: shallow-water particle velocity c * eta / h; swash sheet: the tip moves at
	// dR/dt, slower toward the shoreline during uprush, faster there while it drains
	let eta = disp.y;
	let uWave = clamp( c * eta / ( max( d, 0.0 ) + max( eta, d * -0.8 ) + 0.15 ), -2.5, 4.0 );
	let rel = sat( swr.inland / max( swr.Rt, 0.5 ) );
	let uSwash = dRdt * select( ( 1.0 - rel ) * 0.6 + 0.9, clamp( ( swr.inland + 3.0 ) / ( swr.Rt + 3.0 ), 0.15, 1.0 ), swr.isUp );
	let wSwash = smoothstep( 0.3, 0.05, d );
	let uFlow = mix( uWave, uSwash, wSwash ) * select( 0.0, 1.0, covered || d > 0.02 );

	var o: ShoreSample;
	// the churn of a bore is uneven along the crest: dense in some stretches, torn into patches and
	// lace in others (different for every wave, drifting slowly along it)
	let wwPatch = smoothstep( -0.5, 0.45, perlin2( vec2f( along * 0.06 + frame.time * 0.05, m * 2.9 + 0.4 ) ) );
	o.disp = disp; o.nShore = nShore; o.env = env; o.foam = s0.z * env * mix( 0.3, 1.0, wwPatch ); o.breaking = s0.w; o.u = u; o.dir = dir;
	o.exposure = exposure; o.swashLevel = swashLevel; o.swashCovered = select( 0.0, 1.0, covered ); o.thick = thick;
	o.swashFoam = swashFoam; o.runup = swr.Rt; o.inland = swr.inland; o.dRdt = dRdt; o.tau = swr.tau;
	o.flow = dir * uFlow; o.flowSpeed = uFlow; o.face = face; o.roller = roller;
	return o;
}
`;

}

export class ShoreWaves {

	constructor( terrainGPU ) {

		this.terrain = terrainGPU;
		this.uniforms = new UniformBlock( 'ShoreParams', {
			period: [ 'f32', 9.0 ],
			amplitude: [ 'f32', 0.34 ], // offshore amplitude (H/2)
			variation: [ 'f32', 0.55 ],
			gamma: [ 'f32', 0.78 ],
			// fraction of the break depth over which the lip plunges. Also sets how fast the breaking state
			// changes along a crest whose height varies: wide enough that a broken section joins the clean
			// face through a shoulder where the lip is still falling (peeling), not a vertical cut
			breakSpan: [ 'f32', 0.13 ],
			curl: [ 'f32', 1.0 ],
			runup: [ 'f32', 1.0 ],
			enabled: [ 'f32', 1.0 ],
			turbidity: [ 'f32', 0.16 ], // sediment + bubble scattering in the surf zone (1/m)
			// direction texture region (buildDirTexture); dirOn = 0 until it exists
			dirMin: [ 'vec2f', new Vector2() ],
			dirSize: [ 'f32', 1 ],
			dirOn: [ 'f32', 0 ],
		} );
		const F = this.uniforms.fields;
		this.period = F.period;
		this.amplitude = F.amplitude;
		this.variation = F.variation;
		this.gamma = F.gamma;
		this.breakSpan = F.breakSpan;
		this.curl = F.curl;
		this.runup = F.runup;
		this.enabled = F.enabled;
		this.turbidity = F.turbidity;
		this.dirMin = F.dirMin;
		this.dirSize = F.dirSize;
		this.time = G.time;
		this.dirTexture = null;
		// placeholder until buildDirTexture() (a binding needs a texture; dirOn selects the fallback)
		this._dirPlaceholder = new Texture( { label: 'shoreDirPlaceholder', width: 1, height: 1, format: 'rgba32float', data: new Float32Array( [ 1, 0, 0, 1 ] ) } );

		this.module = new ShaderModule( {
			name: 'shore',
			deps: [ commonModule, terrainGPU && terrainGPU.module ],
			uniforms: this.uniforms,
			uniformName: 'shoreP',
			bindings: {
				// float data, read with exact loads: no sampler binding (fragment shaders are at their sampler limit)
				shoreDirTex: { texture: () => this.dirTexture || this._dirPlaceholder },
			},
			code: this._code(),
		} );

	}

	_code() {

		return /* wgsl */`
const SHORE_GRAVITY: f32 = ${ f( GRAVITY ) };
const SHORE_TAU: f32 = ${ f( TAU ) };
const SHORE_BEACH_SLOPE: f32 = ${ f( BEACH_SLOPE ) };
const SHORE_SWASH_UP: f32 = ${ f( SWASH_UP ) };
const SHORE_SWASH_DOWN: f32 = ${ f( SWASH_DOWN ) };
const SHORE_SWASH_OVERSHOOT: f32 = ${ f( SWASH_OVERSHOOT ) };

struct ShoreSample {
	disp: vec3f,
	nShore: vec3f,
	env: f32,
	foam: f32,
	breaking: f32,
	u: f32,
	dir: vec2f,
	exposure: f32,
	swashLevel: f32,
	swashCovered: f32,
	thick: f32,
	swashFoam: f32,
	runup: f32,
	inland: f32,
	dRdt: f32,
	tau: f32,
	flow: vec2f,
	flowSpeed: f32,
	face: f32,
	roller: f32,
};

struct ShoreMedium { scatter: vec3f, absorb: vec3f };

struct ShorePhase { sh: vec4f, T: f32, dir: vec2f, exposure: f32, along: f32, s: f32 };

struct ShoreBreak {
	db: f32, b: f32, Ash: f32, p: f32, meanP: f32, crestPeak: f32, yc: f32, yt: f32,
	H: f32, wBore: f32, Xi: f32, Hb: f32, ycB: f32, ytB: f32, Xc: f32, Wt: f32,
};

struct ShoreProfile { x: f32, y: f32, b: f32, foam: f32, face: f32, roller: f32 };

struct ShorePair { s0: vec4f, s1: vec4f };

struct ShoreRunup { tau: f32, Rt: f32, inland: f32, RhMax: f32, su: f32, sb: f32, isUp: bool };

fn shoreHash1( x: f32 ) -> f32 { return fract( sin( x * 127.1 + 311.7 ) * 43758.5453 ); }

// Bathymetry along the beach that the travel-time field doesn't resolve: a bar with rip channels
// cut through it every ~100 m (irregular spacing and width). Over the bar the waves are bigger and
// break first and farther out (the peaks); in the channels they are much smaller and roll through
// unbroken almost to the shorebreak, so a set never closes out along the whole beach at once.
// Returns 1 over the bar, less in a channel; rip (0..1) is the channel mask.
struct ShoreBar { k: f32, rip: f32 };
fn shoreBar( along: f32 ) -> ShoreBar {
	let w = sin( along * 0.021 + 1.9 ) * 1.4 + sin( along * 0.009 + 0.3 ) * 0.9;
	let r = sin( along * 0.059 + w );
	let width = 0.8 + sin( along * 0.017 + 4.1 ) * 0.08; // channels of different width
	let rip = smoothstep( width, 0.985, r );
	// the bar itself is uneven: broad peaks and lower shoulders
	let bar = 0.9 + ( sin( along * 0.031 + 7.3 ) * 0.6 + sin( along * 0.083 + 1.1 ) * 0.4 ) * 0.14;
	return ShoreBar( bar * ( 1.0 - rip * 0.58 ), rip );
}

// along-shore phase wobble (in periods): crests bend over the uneven bottom (and run ahead in the
// deeper rip channels, where the waves travel faster)
fn shoreWobble( along: f32 ) -> f32 {
	return sin( along * 0.029 + 0.7 ) * 0.07 + sin( along * 0.083 + 2.1 ) * 0.035
		+ sin( along * 0.19 + 0.4 ) * 0.022 + sin( along * 0.37 + 2.6 ) * 0.011
		+ shoreBar( along ).rip * 0.045;
}

// ------------------------------------------------------------ per-wave height

fn shoreWaveAmp( m: f32, along: f32 ) -> f32 {
	// sets: groups of ~7 waves with larger ones in the middle, plus per-wave randomness
	let waveSet = abs( sin( m * ${ f( Math.PI / 7 ) } ) ) * 0.6 + 0.55;
	let rnd = ( shoreHash1( m ) - 0.5 ) * 2.0;
	// along-shore variation so waves peel instead of closing out
	// peaks ~40-50 m wide with lower shoulders between them, different for every wave (the warp keeps
	// them from repeating along the beach); each peak breaks first and peels outward from it
	let warp = sin( along * 0.016 + m * 0.9 ) * 1.6;
	let a1 = sin( along * 0.062 + m * 1.7 + warp );
	let a2 = sin( along * 0.13 + m * 4.1 + 1.3 - warp * 0.7 );
	// (plus a shorter ~20 m variation: bores that rise and sag along the crest, more peel sections)
	let a3 = sin( along * 0.29 + m * 2.3 + warp * 0.5 ) * 0.6 + sin( along * 0.47 + m * 5.9 + 0.8 ) * 0.4;
	let alongV = a1 * 0.6 + a2 * 0.4 + a3 * 0.28;
	return max( shoreP.amplitude * waveSet * ( 1.0 + rnd * shoreP.variation * 0.5 + alongV * shoreP.variation * 0.7 ) * shoreBar( along ).k, 0.02 );
}

// ------------------------------------------------------------ cross-section shape

fn shoreBreakParams( A: f32, d: f32 ) -> ShoreBreak {
	var P: ShoreBreak;
	// break depth for this wave (Green's law shoaling, H = gamma d)
	P.db = pow( A * 3.556 / shoreP.gamma, 0.8 );
	P.b = ( P.db - d ) / ( P.db * shoreP.breakSpan ); // <0 shoaling, 0..1 plunging, >1 bore
	let shoal = pow( 10.0 / clamp( d, 0.35, 10.0 ), 0.25 );
	P.Ash = A * shoal;
	P.p = mix( 1.0, 3.0, smoothstep( -2.5, 0.0, P.b ) );
	P.meanP = 1.0 / sqrt( ( P.p + 0.25 ) * PI );
	P.crestPeak = 1.0 + smoothstep( -1.0, 0.3, P.b ) * 0.22;
	P.yc = P.Ash * 2.0 * ( 1.0 - P.meanP ) * P.crestPeak; // crest height
	P.yt = P.Ash * -2.0 * P.meanP * P.crestPeak; // trough level
	P.H = P.yc - P.yt;
	P.wBore = smoothstep( 0.85, 1.35, P.b );
	P.Xi = P.H * 0.8; // lip throw at impact
	// bore height, limited by the depth and fading out in the last few decimetres
	P.Hb = min( P.H * 0.6, max( d, 0.0 ) * 0.75 ) * ( smoothstep( 0.0, 0.3, d ) * 0.7 + 0.3 );
	P.ycB = mix( P.yc, P.yt * 0.6 + P.Hb, P.wBore ); // crest / roller top
	P.ytB = mix( P.yt, P.yt * 0.6, P.wBore ); // trough
	// the collapsing crest moves to where the lip landed (no shift once the bore has run out of height)
	P.Xc = mix( 0.0, P.Xi - P.Hb * 0.55, P.wBore ) * smoothstep( 0.03, 0.3, P.Hb );
	// horizontal extent of the face: concave tube face while plunging, short convex roller front on the bore
	P.Wt = mix( P.H * mix( 0.25, 0.55, smoothstep( 0.1, 0.9, P.b ) ), P.Hb * 0.6 + 0.08, P.wBore );
	return P;
}

// Whitewater made by the breaking wave at xi (m): the horizontal position relative to the crest's
// rest position, positive shoreward (a parcel's own position, or a fixed world point: the shore
// simulation deposits it where the water actually is, not where the parcel rests).
//  * nothing at all while the lip is in the air: the face and the lip are clear, glassy water
//  * the lip lands in the trough at the plunge point (b ~ 0.9, xi = Xi): whitewater appears there
//    and spreads out from it while the tube collapses behind it
//  * the collapsed tube becomes the roller: whitewater over the front and top of the bore,
//    shedding foam behind it (carried on by ShoreSim)
// whitewater over the face after the plunge: s = 0 at the crest .. 1 at the foot of the face
fn shoreFaceFill( b: f32, s: f32 ) -> f32 {
	// the foot turns white first (where the lip lands), the top of the face last: along a peeling
	// crest the edge of the broken section slants down and forward instead of standing vertical
	let k = ( 1.0 - s ) * 0.45;
	return smoothstep( k + 0.9, k + 1.08, b );
}

fn shoreWhitewater( xi: f32, lam: f32, P: ShoreBreak ) -> f32 {
	let landed = smoothstep( 0.86, 0.99, P.b );
	let spread = sat( ( P.b - 0.9 ) / 0.45 );
	let reach = P.Xi * 0.25 + spread * ( P.Xi * 0.9 + 1.0 ); // radius around the plunge point
	let impact = landed * smoothstep( reach, reach * 0.6, abs( xi - P.Xi ) ) * ( 1.0 - smoothstep( 1.4, 1.9, P.b ) );
	let toe = P.Xc + P.Wt;
	// the collapsing tube turns white from its foot (next to the plunge point) up to the crest
	let faceFill = shoreFaceFill( P.b, sat( ( xi - P.Xc ) / max( P.Wt, 0.05 ) ) );
	let ahead = exp( ( xi - toe ) * -3.0 ) * P.wBore;
	let behind = exp( ( P.Xc - xi ) / lam * -16.0 ) * P.wBore;
	let roller = select( select( max( faceFill, P.wBore ), behind, xi < P.Xc ), ahead, xi > toe );
	return sat( max( impact, roller ) );
}

// the cross-section for break parameters P (see shoreBreakParams)
// u: local phase in [-0.5, 0.5], crest at 0, u < 0 in front (shoreward) of the crest
// Returns x: shoreward displacement, y: height above mean, b: breaking progress (+ foam, face, roller withFoam)
fn shoreProfile( u: f32, lam: f32, P: ShoreBreak, withFoam: bool ) -> ShoreProfile {
	// --- shoaling: peaked (cnoidal-like) crest, the front compressed by a phase skew
	let skew = smoothstep( -3.0, 0.0, P.b ) * 0.55;
	let phi = u - skew * ( 1.0 - cos( u * SHORE_TAU ) ) / SHORE_TAU;
	let c = max( ( cos( phi * SHORE_TAU ) + 1.0 ) * 0.5, 0.0 ); // pow() of a rounding-negative base is NaN
	let yPre = P.Ash * 2.0 * ( pow( c, P.p ) - P.meanP ) * P.crestPeak;
	let Q = smoothstep( -3.0, 0.0, P.b ) * 0.25 + 0.1;
	let xPre = sin( u * SHORE_TAU ) * P.Ash * Q;

	// --- plunging / bore profile. Front: the upper uf of the phase is an elliptic arc from the
	// crest down to the trough (concave tube face -> convex roller front), the rest of the
	// front is trough, stretched to meet the next wave. Back: the shoaling back, decaying
	// exponentially behind the bore.
	let uf = 0.09;
	let inFace = u > - uf;
	let th = clamp( - u / uf, 0.0, 1.0 ) * ${ f( Math.PI / 2 ) };
	let fx = mix( 1.0 - cos( th ), sin( th ), P.wBore );
	let fy = mix( 1.0 - sin( th ), cos( th ), P.wBore );
	let sTr = clamp( ( - u - uf ) / ( 0.5 - uf ), 0.0, 1.0 );
	let ul = u * lam;
	let xFront = select( mix( P.Xc + P.Wt, lam * 0.5, sTr ), P.Xc + P.Wt * fx, inFace ) + ul;
	let yFront = select( P.ytB, P.ytB + ( P.ycB - P.ytB ) * fy, inFace );
	let cb = pow( max( ( cos( u * ( SHORE_TAU * 0.85 ) ) + 1.0 ) * 0.5, 0.0 ), P.p );
	let yBack = P.ytB + ( P.ycB - P.ytB ) * mix( cb, exp( u * -7.0 ), P.wBore );
	let xBack = P.Xc * exp( u * -6.0 ) * smoothstep( 0.5, 0.35, u ) + xPre * ( 1.0 - P.wBore );
	let front = u < 0.0;
	let wC = smoothstep( -0.35, 0.25, P.b ) * shoreP.curl;
	var r: ShoreProfile;
	r.x = mix( xPre, select( xBack, xFront, front ), wC );
	r.y = mix( yPre, select( yBack, yFront, front ), wC );
	r.b = P.b;
	if ( withFoam ) {
		// --- whitewater (a function of where the parcel is now, see shoreWhitewater) and, per parcel, the
		// clear face of the plunging wave and the relief of the roller
		r.foam = shoreWhitewater( r.x - u * lam, lam, P );
		let onFace = front && inFace;
		let faceFill = shoreFaceFill( P.b, fx );
		// the clear, concave face of a plunging wave (WaterSurface keeps the foam carried by the water off it)
		r.face = select( 0.0, 1.0, onFace ) * smoothstep( -0.4, 0.0, P.b ) * ( 1.0 - faceFill );
		// turbulent relief of the whitewater roller (m): its front and the top it tumbles over
		r.roller = select( exp( u * -25.0 ), select( 0.0, 1.0, inFace ), front ) * P.wBore * P.Hb * wC;
	}
	return r;
}

// ( x, y, foam, b )
fn shoreShape( u: f32, A: f32, d: f32, lam: f32 ) -> vec4f {
	let s = shoreProfile( u, lam, shoreBreakParams( A, d ), true );
	return vec4f( s.x, s.y, s.foam, s.b );
}

// the cross-section at u and at u + du (for the surface normal) in one call:
// ( x0, y0, foam, b ), ( x1, y1, face, roller )
fn shoreShapePair( u: f32, du: f32, A: f32, d: f32, lam: f32 ) -> ShorePair {
	let P = shoreBreakParams( A, d );
	let s0 = shoreProfile( u, lam, P, true );
	let s1 = shoreProfile( u + du, lam, P, false );
	return ShorePair( vec4f( s0.x, s0.y, s0.foam, s0.b ), vec4f( s1.x, s1.y, s0.face, s0.roller ) );
}

// the surface at a fixed WORLD point (for the Eulerian shore simulation): whitewater there and
// the water height there (the parcel shown at this point rests ~x up-wave: first-order inverse
// of the horizontal displacement, which is large on a breaking wave)
// ( foam, height, displacement of the parcel resting here, b )
fn shoreWorld( u: f32, A: f32, d: f32, lam: f32, env: f32 ) -> vec4f {
	let P = shoreBreakParams( A, d );
	let s0 = shoreProfile( u, lam, P, false );
	let s1 = shoreProfile( u + s0.x * env / lam, lam, P, false );
	return vec4f( shoreWhitewater( - u * lam, lam, P ), s1.y, s0.x, P.b );
}

// the bore that follows the plunge: roller height Hb, horizontal extent of its front Wt, forward
// shift of the crest Xc (to where the lip landed), bore weight (0 while plunging .. 1)
fn shoreBore( A: f32, d: f32 ) -> vec4f {
	let P = shoreBreakParams( A, d );
	return vec4f( P.Hb, P.Wt, P.Xc, P.wBore );
}

// breaking progress b, wave height H, trough level (relative to mean) and how far the lip is thrown
fn shoreCrest( A: f32, d: f32 ) -> vec4f {
	let P = shoreBreakParams( A, d );
	return vec4f( P.b, P.yc - P.yt, P.ytB, P.Xi );
}

// Depth that sets the breaking state of the wave a parcel belongs to: the depth under that wave's
// crest, not under the parcel. Breaking is a property of the wave: a parcel ahead of the crest is
// in shallower water and would otherwise "break" first (whitewater creeping up the foot of a still
// glassy face). Near the troughs it hands over to the local depth, where the neighbouring wave
// takes over (the profile stays continuous at u = +-0.5). u: local phase, lam: local wavelength.
fn shoreBreakDepth( xz: vec2f, dir: vec2f, u: f32, lam: f32, d: f32 ) -> f32 {
	let pc = xz + dir * ( u * lam );
	let dc = frame.seaLevel - terrainHeightAt( pc );
	return mix( dc, d, smoothstep( 0.3, 0.5, abs( u ) ) );
}

// ------------------------------------------------------------ cheap wave direction lookup

// vec3( dir.x, dir.z, exposure ) from the direction texture (bilinear from 4 loads)
fn shoreDirAt( xz: vec2f ) -> vec3f {
	let res = f32( textureDimensions( shoreDirTex ).x );
	let fp = ( xz - shoreP.dirMin ) / shoreP.dirSize * res - 0.5;
	let fc = clamp( fp, vec2f( 0.0 ), vec2f( res - 1.001 ) );
	let i = vec2i( floor( fc ) );
	let t = fract( fc );
	let a = textureLoad( shoreDirTex, i, 0 );
	let b = textureLoad( shoreDirTex, i + vec2i( 1, 0 ), 0 );
	let c = textureLoad( shoreDirTex, i + vec2i( 0, 1 ), 0 );
	let d = textureLoad( shoreDirTex, i + vec2i( 1, 1 ), 0 );
	return mix( mix( a, b, t.x ), mix( c, d, t.x ), t.y ).xyz;
}

// ------------------------------------------------------------ surf zone water

// Optical properties of the water stirred up by breaking waves: suspended sand and fine bubbles
// scatter light (milky, luminous), fine sediment and dissolved matter absorb blue. Returns the
// extra { scatter, absorb } coefficients (1/m) that make the surf zone turquoise, not ocean-clear.
fn shoreSurfMedium( xz: vec2f, depth: f32 ) -> ShoreMedium {
	var k = 0.0;
	if ( depth < 4.5 && depth > -0.2 ) {
		var expo: f32;
		if ( shoreP.dirOn > 0.5 ) { expo = shoreDirAt( xz ).z; } else { expo = sat( length( terrainShoreSample( xz ).yz ) * 1.4 ); }
		k = smoothstep( 4.5, 1.2, depth ) * smoothstep( -0.2, 0.15, depth ) * expo * shoreP.turbidity * shoreP.enabled;
	}
	return ShoreMedium( vec3f( 0.9, 1.0, 0.85 ) * k, vec3f( 0.1, 0.2, 0.62 ) * k );
}

// ------------------------------------------------------------ evaluation at a point

// Local wave phase data at a (Lagrangian) point: shared by evaluate() and the crest finder.
fn shorePhaseAt( xz: vec2f ) -> ShorePhase {
	let sh = terrainShoreSample( xz );
	let T = sh.x;
	let dirE = vec2f( sh.y, sh.z );
	let exposure = length( dirE );
	let dir = dirE / max( exposure, 1e-4 );
	let along = dot( xz, vec2f( - dir.y, dir.x ) );
	let s = ( frame.time - T ) / shoreP.period + shoreWobble( along );
	return ShorePhase( sh, T, dir, exposure, along, s );
}

// ------------------------------------------------------------ light through thin crests

// Water path (m) along the refracted view ray Tv (unit, inside the water) from the surface point
// with rest position lagXZ until the ray leaves through the other side of the wave, or 1e4 if
// it doesn't within a few metres. The upper part of a steep wave is only a few metres thick
// horizontally: the view ray crosses it and exits into the sky behind, which is what makes
// breaking faces and crests glow turquoise. Marches the analytic cross-section (up to 3 steps).
fn shoreCrestPath( p: vec2f, d: f32, T: vec3f ) -> f32 {
	var out = 1e4;
	if ( d >= 6.0 || shoreP.enabled <= 0.0 ) { return out; } // (before the phase lookup)
	let ph = shorePhaseAt( p );
	let tXi = dot( T.xz, ph.dir ); // shoreward component of the ray
	let env = smoothstep( 26.0, 13.0, d ) * sat( ph.exposure * 1.4 ) * shoreP.enabled;
	// rays heading out through the back of the wave (a view from the beach side), near breakers
	if ( env > 0.05 && tXi < -0.05 && d < 6.0 ) {
		let lam = sqrt( clamp( d, 0.3, 25.0 ) * SHORE_GRAVITY ) * shoreP.period;
		let m = floor( ph.s + 0.5 );
		let u = ph.s - m;
		let A = shoreWaveAmp( m, ph.along );
		let P = shoreBreakParams( A, shoreBreakDepth( p, ph.dir, u, lam, d ) );
		let s0 = shoreProfile( u, lam, P, false );
		let y0 = s0.y * env;
		// only the upper part of steep (nearly breaking) waves is thin enough to see through
		if ( y0 > A * 0.2 && P.b > -1.5 ) {
			let xi0 = - u * lam + s0.x * env;
			let slope = T.y / - tXi; // ray rise per metre of horizontal travel
			var prevGap = 0.0;
			var prevDist = 0.0;
			var off = 1.1;
			for ( var k = 0; k < 3; k++ ) {
				let uk = min( u + off / lam, 0.5 );
				let sk = shoreProfile( uk, lam, P, false );
				let dist = abs( xi0 - ( - uk * lam + sk.x * env ) );
				// ray height above the surface there (> 0: the ray has left the water)
				let gap = y0 + slope * dist - sk.y * env;
				if ( gap > 0.0 ) {
					let fr = - prevGap / max( gap - prevGap, 1e-4 );
					out = mix( prevDist, dist, sat( fr ) ) / - tXi;
					break;
				}
				prevGap = gap;
				prevDist = dist;
				off *= 2.6;
			}
		}
	}
	return out;
}

// ------------------------------------------------------------ swash

// Run-up of the most recent wave at a point on the beach (distances in metres up the beach face).
// The run-up is compared with the height of the sand (converted with the nominal beach slope), so
// the front is exact at the waterline and follows the contours of the sand. sh: terrainShoreSample( xz ).
fn shoreSwashRunup( sh: vec4f, along: f32, groundH: f32 ) -> ShoreRunup {
	let Tp = shoreP.period;
	let exposure = length( vec2f( sh.y, sh.z ) );
	let Ts = sh.w;
	let inland = max( groundH - frame.seaLevel, 0.0 ) / SHORE_BEACH_SLOPE;
	let ss = ( frame.time - Ts ) / Tp + shoreWobble( along );
	let ms = floor( ss );
	let tau = ss - ms; // 0..1 time since that wave's bore reached the shoreline
	let Am = shoreWaveAmp( ms, along );
	// vertical run-up ~ H on this gentle beach, converted to a horizontal excursion
	let RhMax = Am * 2.1 * shoreP.runup * sat( exposure * 1.4 ) / SHORE_BEACH_SLOPE;
	// decelerating uprush, then a backwash that starts slowly and accelerates as the sheet drains
	let su = sat( tau / SHORE_SWASH_UP );
	let sb = sat( ( tau - SHORE_SWASH_UP ) / SHORE_SWASH_DOWN );
	let isUp = tau < SHORE_SWASH_UP;
	let Rh = select( 1.0 - pow( sb, 1.6 ), 1.0 - pow( 1.0 - su, 1.5 ), isUp ) * RhMax - 0.3;
	// the front is lobed, not a straight line: each wave runs up a little differently along the beach
	let lobes = sin( along * 0.61 + ms * 2.3 ) * 0.5 + sin( along * 1.73 + ms * 5.1 ) * 0.3 + sin( along * 4.3 + ms * 1.7 ) * 0.2;
	// the backwash never quite exposes the lower beach face: a film of water always covers the
	// first decimetres past the shoreline, so the sea never meets the sand along mesh triangles
	let Rt = max( Rh + lobes * ( max( Rh, 0.0 ) * 0.07 + 0.35 ), 0.35 ) * shoreP.enabled;
	return ShoreRunup( tau, Rt, inland, RhMax, su, sb, isUp );
}

// Water film thickness clipped at the leading edge of the swash sheet, for the water shader's
// edge fade: min( thickness, distance to the front (m) * 0.08 ). Only evaluated where the film is
// thin, so the sheet ends on the analytic front instead of the mesh triangles at ~no cost.
fn shoreSwashEdge( p: vec2f, t: f32 ) -> vec4f {
	var out = vec4f( t, 1e3, 0.0, 0.0 );
	if ( t < 0.2 ) {
		let g = terrainHeightAt( p );
		if ( g > frame.seaLevel ) {
			let ph = shorePhaseAt( p );
			let r = shoreSwashRunup( ph.sh, ph.along, g );
			let front = r.Rt - r.inland;
			out = vec4f( min( t, front * 0.08 ), front, r.tau, r.Rt );
		}
	}
	return out;
}

fn shoreSwashClip( p: vec2f, t: f32 ) -> f32 {
	return shoreSwashEdge( p, t ).x;
}

// ------------------------------------------------------------ evaluate()
// Returns displacement relative to (xz, seaLevel), foam, breaking indicator and the
// swash surface level (absolute height) for this point. shoreEvaluate (withNormal, the water mesh) also
// gives face: 1 on the clear concave face of a plunging wave, roller: relief of the whitewater (m).
// shoreEvaluateWorld: the shore simulation's view (a fixed world point instead of a water parcel): foam and
// height are those of the water shown at xz, the displacement is not meaningful.
${ evaluateCode( 'shoreEvaluate', 'normal' ) }
${ evaluateCode( 'shoreEvaluateNoNormal', 'plain' ) }
${ evaluateCode( 'shoreEvaluateWorld', 'world' ) }
`;

	}

	// ------------------------------------------------------------ cheap wave direction lookup

	// Low-resolution texture of the wave direction and exposure over a region (one bilinear
	// fetch from 4 loads instead of the 4 exact loads of the shore field for each of 4 corners) for
	// per-pixel effects near the beach. region: { min: Vector2, size }. WGSL: shoreDirAt( xz ) ->
	// vec3f( dir.x, dir.z, exposure ).
	buildDirTexture( { min, size, res = 128 } ) {

		// the shore field (T, dirX, dirZ, exposure / swash time) as float data on the CPU
		const T = this.terrain;
		const field = T.shoreField || null;
		const data = field ? field.data : T.shoreData || T.shoreTexture?.image?.data || T.shoreTexture?.pendingData;
		const fres = field ? field.res : T.shoreRes;
		if ( ! data || ! fres ) {

			console.warn( 'ShoreWaves.buildDirTexture: no shore field data on the terrain; using terrainShoreSample instead' );
			return null;

		}

		const origin = T.origin, tsize = T.size;
		const out = new Float32Array( res * res * 4 );
		for ( let j = 0; j < res; j ++ ) for ( let i = 0; i < res; i ++ ) {

			const x = min.x + ( i + 0.5 ) / res * size, z = min.y + ( j + 0.5 ) / res * size;
			const fx = Math.min( Math.max( ( x - origin ) / tsize * fres - 0.5, 0 ), fres - 1.001 );
			const fz = Math.min( Math.max( ( z - origin ) / tsize * fres - 0.5, 0 ), fres - 1.001 );
			const i0 = Math.floor( fx ), j0 = Math.floor( fz ), tx = fx - i0, tz = fz - j0;
			const at = ( c ) => {

				const a = data[ ( j0 * fres + i0 ) * 4 + c ], b = data[ ( j0 * fres + i0 + 1 ) * 4 + c ];
				const cc = data[ ( ( j0 + 1 ) * fres + i0 ) * 4 + c ], d = data[ ( ( j0 + 1 ) * fres + i0 + 1 ) * 4 + c ];
				return ( a * ( 1 - tx ) + b * tx ) * ( 1 - tz ) + ( cc * ( 1 - tx ) + d * tx ) * tz;

			};

			const dx = at( 1 ), dz = at( 2 );
			const e = Math.hypot( dx, dz ) || 1e-4;
			const k = ( j * res + i ) * 4;
			out[ k ] = dx / e;
			out[ k + 1 ] = dz / e;
			out[ k + 2 ] = Math.min( 1, e * 1.4 );
			out[ k + 3 ] = 1;

		}

		// float data, read with exact loads: no sampler binding (fragment shaders are at their sampler limit)
		const t = new Texture( { label: 'shoreDir', width: res, height: res, format: 'rgba32float', data: out } );
		this.dirTexture = t;
		this.dirMin.value.copy( min );
		this.dirSize.value = size;
		this.uniforms.fields.dirOn.value = 1;
		this.dirRes = res;
		return t;

	}

}

import { Texture, ShaderModule, commonModule } from '../engine/webgpu.js';

// Surf-zone foam: the lace texture shared by the shore simulation, and the foam look used by the
// water shader (hooks called from WaterSurface.fragment and WaterMaterial.shade).
//
// Whitewater is a volume of bubbles: a dense mat that is bright from every side, with a lumpy,
// bubbly surface (darker in its own dips), tearing into patches and then into lace (thin bubble
// strands around clear holes) as it decays. Thin foam is translucent over the water colour.
//
// WGSL (this.module, prefix surfFoam; deps: shoreSim.module, shore.module):
//   struct SurfFoamArgs { coverage, foam, footprint, depth, bubbles: f32, lagXZ: vec2f, normal: vec3f,
//                         baseNormal: vec3f, fresh, sim: f32, simState: vec4f, roller: f32, P: vec3f }
//     (P: world position of the fragment — the pattern lives in world space; set it!)
//   struct SurfFoamInfo { foam, density, height, surf, ww, relief, selfShadow, cavity: f32,
//                         reliefPat, reliefK, thinPat, thinK, bubPat, bubK: f32 }
//     (height / relief = pattern x weight; the *Pat / *K split is what the lighting differentiates)
//   fn surfFoamShading( a: SurfFoamArgs ) -> SurfFoamInfo
//   fn surfFoamLight( info: SurfFoamInfo, N: vec3f, L: vec3f, V: vec3f, sun: vec3f, P: vec3f ) -> vec3f
//   fn surfFoamFlowLace( q: vec2f, flow: vec2f, salt: f32 ) -> vec4f

export const LACE_TILE = 3.5; // metres per tile of the lace texture

// Tileable lace texture (generated once on the CPU, with CPU mipmaps: no GPU pipeline needed)
//   R: distance to the nearest bubble strand (warped cell edges + noise contours), 0 on a strand,
//      1 in the middle of a hole: thresholding it by the foam amount gives a dense mat, foam with
//      holes, lace and thin strands as the foam decays
//   G: small bubbles clustered along the strands
//   B: soft mottling (foam density variation)
//   A: per-cell random value (staggers when stranded foam pops)
let cachedLace = null;

export function makeLaceTexture( size = 512 ) {

	if ( cachedLace ) return cachedLace;
	const t0 = performance.now();
	const data = laceData( size );
	const mips = [ { data, width: size, height: size } ];
	let src = data, s = size;
	while ( s > 1 ) {

		const h = s >> 1;
		const dst = new Uint8Array( h * h * 4 );
		for ( let y = 0; y < h; y ++ ) for ( let x = 0; x < h; x ++ ) for ( let c = 0; c < 4; c ++ ) {

			const a = src[ ( ( 2 * y ) * s + 2 * x ) * 4 + c ], b = src[ ( ( 2 * y ) * s + 2 * x + 1 ) * 4 + c ];
			const d = src[ ( ( 2 * y + 1 ) * s + 2 * x ) * 4 + c ], e = src[ ( ( 2 * y + 1 ) * s + 2 * x + 1 ) * 4 + c ];
			dst[ ( y * h + x ) * 4 + c ] = ( a + b + d + e + 2 ) >> 2;

		}

		mips.push( { data: dst, width: h, height: h } );
		src = dst;
		s = h;

	}

	// sampled with smpAnisoRepeat (linear, mipmapped, repeat)
	const tex = new Texture( { label: 'surfLace', width: size, height: size, format: 'rgba8unorm', mips: mips.length, usage: [ 'sample', 'copyDst' ] } );
	for ( let m = 0; m < mips.length; m ++ ) tex.upload( mips[ m ].data, { mip: m } );
	tex.userData = { ms: performance.now() - t0, size };
	// the same pattern for shaders with no sampler to spare: nearest, read with loads, filtered by
	// hand (see shoreSimLaceLoad)
	const near = new Texture( { label: 'surfLaceNearest', width: size, height: size, format: 'rgba8unorm', data, usage: [ 'sample', 'copyDst' ] } );
	tex.userData.nearest = near;
	tex.userData.mips = mips;
	cachedLace = tex;
	return tex;

}

function laceData( size ) {

	const data = new Uint8Array( size * size * 4 );
	const hash = ( x, y, s ) => {

		let h = ( x * 374761393 + y * 668265263 + s * 2246822519 ) | 0;
		h = Math.imul( h ^ ( h >>> 13 ), 1274126177 );
		h ^= h >>> 16;
		return ( h >>> 0 ) / 4294967296;

	};

	const vnoise = ( x, y, n, s ) => {

		const i = Math.floor( x ), j = Math.floor( y );
		const fx = x - i, fy = y - j;
		const ux = fx * fx * ( 3 - 2 * fx ), uy = fy * fy * ( 3 - 2 * fy );
		const w = ( a ) => ( ( a % n ) + n ) % n;
		const a = hash( w( i ), w( j ), s ), b = hash( w( i + 1 ), w( j ), s );
		const c = hash( w( i ), w( j + 1 ), s ), d = hash( w( i + 1 ), w( j + 1 ), s );
		return ( a * ( 1 - ux ) + b * ux ) * ( 1 - uy ) + ( c * ( 1 - ux ) + d * ux ) * uy;

	};

	const fbm = ( x, y, n, s, oct = 3 ) => {

		let v = 0, a = 0.5, t = 0;
		for ( let o = 0; o < oct; o ++ ) {

			v += vnoise( x * ( 1 << o ), y * ( 1 << o ), n * ( 1 << o ), s + o * 17 ) * a;
			t += a;
			a *= 0.5;

		}

		return v / t;

	};

	// Voronoi F1, F2 and nearest cell id on an n x n periodic jittered grid (coordinates in cells)
	const voronoi = ( x, y, n, s ) => {

		const i = Math.floor( x ), j = Math.floor( y );
		let f1 = 9, f2 = 9, id = 0;
		for ( let dj = - 1; dj <= 1; dj ++ ) for ( let di = - 1; di <= 1; di ++ ) {

			const ci = i + di, cj = j + dj;
			const wi = ( ( ci % n ) + n ) % n, wj = ( ( cj % n ) + n ) % n;
			const px = ci + 0.15 + 0.7 * hash( wi, wj, s ), py = cj + 0.15 + 0.7 * hash( wi, wj, s + 1 );
			const d = Math.hypot( px - x, py - y );
			if ( d < f1 ) {

				f2 = f1; f1 = d; id = hash( wi, wj, s + 2 );

			} else if ( d < f2 ) f2 = d;

		}

		return [ f1, f2, id ];

	};

	const sstep = ( a, b, x ) => {

		const t = Math.min( 1, Math.max( 0, ( x - a ) / ( b - a ) ) );
		return t * t * ( 3 - 2 * t );

	};

	// pass 1: warped coordinates and the contour noise at every texel
	const N = size * size;
	const UU = new Float32Array( N ), VV = new Float32Array( N ), NC = new Float32Array( N );
	for ( let py = 0; py < size; py ++ ) for ( let px = 0; px < size; px ++ ) {

		const u = ( px + 0.5 ) / size, v = ( py + 0.5 ) / size;
		// two-level domain warp: organic, curvy strands
		const w1x = ( fbm( u * 3, v * 3, 3, 3 ) - 0.5 ) * 0.16, w1y = ( fbm( u * 3 + 5.2, v * 3 + 1.3, 3, 7 ) - 0.5 ) * 0.16;
		const w2x = ( fbm( ( u + w1x ) * 9, ( v + w1y ) * 9, 9, 13 ) - 0.5 ) * 0.07, w2y = ( fbm( ( u + w1x ) * 9 + 2.7, ( v + w1y ) * 9, 9, 17 ) - 0.5 ) * 0.07;
		const k = py * size + px;
		UU[ k ] = u + w1x + w2x;
		VV[ k ] = v + w1y + w2y;
		NC[ k ] = fbm( UU[ k ] * 6, VV[ k ] * 6, 6, 91, 3 );

	}

	// pass 2: distance to the nearest strand
	const N1 = 16, half = 0.5 / N1;
	const D = new Float32Array( N );
	for ( let py = 0; py < size; py ++ ) for ( let px = 0; px < size; px ++ ) {

		const u = ( px + 0.5 ) / size, v = ( py + 0.5 ) / size;
		const k = py * size + px;
		const uu = UU[ k ], vv = VV[ k ];
		// strands 1: edges of a warped cell network (distance to the edge ~ (F2 - F1) / 2, in cells)
		const [ a1, b1, id1 ] = voronoi( uu * N1, vv * N1, N1, 11 );
		const dCells = ( b1 - a1 ) * 0.5 / N1;
		// strands 2: contour loops of the warped noise; distance ~ |n - c| / |grad n| (texture units)
		const n1 = NC[ k ];
		const xl = ( px + size - 1 ) % size, xr = ( px + 1 ) % size, yd = ( py + size - 1 ) % size, yu = ( py + 1 ) % size;
		const gx = ( NC[ py * size + xr ] - NC[ py * size + xl ] ) * size * 0.5;
		const gy = ( NC[ yu * size + px ] - NC[ yd * size + px ] ) * size * 0.5;
		const g = Math.max( Math.hypot( gx, gy ), 0.5 );
		const dLoops = Math.min( Math.abs( n1 - 0.5 ), Math.abs( n1 - 0.36 ), Math.abs( n1 - 0.64 ) ) / g;
		// normalised by half a cell: 0 on a strand, ~1 in the middle of a hole. Irregular hole edges
		// (fine noise) and places where the strands break up (gaps).
		const hi = fbm( u * 24, v * 24, 24, 5, 2 );
		const gap = sstep( 0.52, 0.36, fbm( u * 10 + 3.1, v * 10, 10, 31 ) );
		const d = Math.min( dCells * 1.35 + 0.004, dLoops ) / half * ( 0.75 + 0.5 * hi ) + gap * 0.22;
		const mott = fbm( u * 3, v * 3, 3, 71, 4 );
		// bubbles: small dots, clustered near the strands
		const N3 = 120;
		const [ a3, , id3 ] = voronoi( u * N3, v * N3, N3, 61 );
		const rad = 0.1 + 0.22 * id3;
		const dot = sstep( rad, rad * 0.35, a3 ) * ( id3 > 0.45 ? 1 : 0 );
		const bub = dot * ( 0.25 + 0.75 * sstep( 0.5, 0.1, d ) );
		D[ k ] = Math.min( 1, d );
		data[ k * 4 + 1 ] = Math.round( Math.min( 1, bub ) * 255 );
		data[ k * 4 + 2 ] = Math.round( mott * 255 );
		data[ k * 4 + 3 ] = Math.round( id1 * 255 );

	}

	// pass 3: rounded holes: blurred distance inside the holes, the exact one near the strands
	const D0 = new Float32Array( D );
	const T = new Float32Array( N );
	for ( let it = 0; it < 2; it ++ ) {

		for ( let py = 0; py < size; py ++ ) for ( let px = 0; px < size; px ++ ) {

			let s = 0;
			for ( let o = - 2; o <= 2; o ++ ) s += D[ py * size + ( ( px + o + size ) % size ) ];
			T[ py * size + px ] = s / 5;

		}

		for ( let py = 0; py < size; py ++ ) for ( let px = 0; px < size; px ++ ) {

			let s = 0;
			for ( let o = - 2; o <= 2; o ++ ) s += T[ ( ( py + o + size ) % size ) * size + px ];
			D[ py * size + px ] = s / 5;

		}

	}

	for ( let k = 0; k < N; k ++ ) data[ k * 4 ] = Math.round( ( D0[ k ] + ( D[ k ] - D0[ k ] ) * sstep( 0.12, 0.45, D0[ k ] ) ) * 255 );
	return data;

}

// Foam look hooks for the water shader.
//   surface.foamShading = surfFoam   (WaterSurface.fragment calls surfFoamShading)
//   surfFoamLight( info, N, L, V, sun, P )   (WaterMaterial.shade)
//
// The pattern lives in world space, never in the coordinates of the displaced surface (those are
// squeezed and stretched by the big horizontal motion of the shore waves and would draw the foam
// into streaks). It is carried by the water with a dual-phase flow map: two copies of the pattern,
// half a cycle apart, each advected by the local flow (from ShoreSim) for one cycle and then
// re-placed at random, cross-faded so neither is ever stretched for long and the resets never show.
// Steep whitewater faces (bore / roller fronts) use a vertical projection that rolls down the face.
export class SurfFoam {

	constructor( { shoreSim } ) {

		this.sim = shoreSim;
		this.bump = 0.7; // relief of the whitewater and of thick foam (normal perturbation strength)
		this.period = 1.2; // s, flow map cycle
		this.maxFlow = 2.5; // m/s, the pattern lags behind faster flow (bounds the distortion per cycle)
		this.module = new ShaderModule( {
			name: 'surfFoam',
			deps: [ commonModule, shoreSim.module, shoreSim.shore.module ],
			bindings: { surfFoamLaceTex: { texture: shoreSim.lace } },
			code: this._code(),
		} );

	}

	_code() {

		const f = ( x ) => {

			const s = String( x );
			return s.includes( '.' ) || s.includes( 'e' ) ? s : s + '.0';

		};

		return /* wgsl */`
struct SurfFoamArgs {
	coverage: f32,
	foam: f32,
	footprint: f32,
	depth: f32,
	bubbles: f32,
	lagXZ: vec2f,
	normal: vec3f,
	baseNormal: vec3f,
	fresh: f32,
	sim: f32,
	simState: vec4f,
	roller: f32,
	P: vec3f,
};

struct SurfFoamInfo {
	foam: f32,
	density: f32,
	height: f32,
	surf: f32,
	ww: f32,
	relief: f32,
	selfShadow: f32,
	cavity: f32,
	// relief split into world-space patterns and their weights: the weights come from values
	// interpolated across the water mesh (fresh whitewater, depth, footprint), so the screen-space
	// gradient of a weight is constant per triangle; differentiating the product drew every mesh
	// triangle as a flat facet into the foam. Only the patterns are differentiated.
	reliefPat: f32, // whitewater lumps (m), relief = reliefPat * reliefK
	reliefK: f32,
	thinPat: f32, // thin foam: height = thinPat * thinK + bubPat * bubK
	thinK: f32,
	bubPat: f32,
	bubK: f32,
};

// Henyey-Greenstein phase (1/sr)
fn surfFoamPhaseHG( cosT: f32, g: f32 ) -> f32 {
	let g2 = g * g;
	return ( ( 1.0 - g2 ) / ( 4.0 * PI ) ) / pow( max( 1.0 + g2 - cosT * 2.0 * g, 1e-4 ), 1.5 );
}

fn surfFoamHash11( x: f32 ) -> f32 { return fract( sin( x * 91.7 + 17.3 ) * 43758.5453 ); }

// Lace distance (0 on a bubble strand .. 1 in a hole) at pattern coordinates q (m), carried by
// flow (m/s in the same coordinates) with the dual-phase flow map. salt decorrelates layers.
fn surfFoamFlowLace( q: vec2f, flow: vec2f, salt: f32 ) -> vec4f {
	let t = frame.time / ${ f( this.period ) };
	let v = clamp( flow, vec2f( - ${ f( this.maxFlow ) } ), vec2f( ${ f( this.maxFlow ) } ) ) * ${ f( this.period ) };
	var out = vec4f( 0.0 );
	for ( var k = 0; k < 2; k++ ) {
		let tk = t + ( f32( k ) * 0.5 + salt * 0.37 );
		let ph = fract( tk );
		let cycle = floor( tk ) + ( f32( k ) * 13.1 + salt * 5.7 );
		let jitter = vec2f( surfFoamHash11( cycle ), surfFoamHash11( cycle + 0.5 ) ) * 7.0;
		let p = ( q - v * ( ph - 0.5 ) ) / ${ f( LACE_TILE ) } + jitter;
		let w = 1.0 - abs( ph * 2.0 - 1.0 );
		out += textureSample( surfFoamLaceTex, smpAnisoRepeat, p ) * w;
	}
	return out; // the two weights always add up to 1
}

fn surfFoamBigAt( qq: vec2f, pflow: vec2f ) -> f32 {
	return sqrt( surfFoamFlowLace( qq / 6.0, pflow / 6.0, 2.0 ).x );
}

// coverage: total foam amount (0..1, all sources); foam: the default (offshore whitecap) foam;
// footprint: pixel size on the surface (m); depth: sea depth; bubbles: fine bubble detail;
// normal: surface normal; fresh: whitewater made by the breaking wave right here (roller,
// plunge point, swash front); sim: foam carried by the water (ShoreSim, already kept off the
// clear face of plunging waves); simState: shoreSimSample() at this pixel; roller: relief of
// the whitewater roller (m)
fn surfFoamShading( a: SurfFoamArgs ) -> SurfFoamInfo {
	// world position of the fragment (the pattern is in world space); a caller that left P unset
	// (zero) gets the rest position instead: close, but the lace then rides the horizontal wave motion
	let P = select( a.P, vec3f( a.lagXZ.x, frame.seaLevel, a.lagXZ.y ), all( a.P == vec3f( 0.0 ) ) );
	let xz = P.xz;
	let coverage = a.coverage;
	var opacity = a.foam;
	var density = sat( coverage );
	var height = 0.0;
	var wwOut = 0.0; // how much of it is whitewater (deeper crevices)
	var wwRelief = 0.0; // relief of the whitewater (m)
	var wwShadow = 1.0; // sun visibility inside the churn
	var wwCav = 1.0; // sky visibility in its crevices
	var reliefPat = 0.0; var reliefK = 0.0;
	var thinPat = 0.0; var thinK = 0.0;
	var bubPat = 0.0; var bubK = 0.0;
	// surf look near the beach, the default whitecap look offshore
	let surf = smoothstep( 7.0, 3.0, a.depth ) * shoreSimInside( shoreSimUvOf( xz ) );
	if ( surf > 0.0 && coverage > 0.04 ) {

		// flow of the water here, from the shore simulation (along the local wave direction)
		let dir = shoreDirAt( xz ).xy;
		let speed = a.simState.w;
		let flow = dir * speed;

		// --- pattern: world-space lace carried by the flow; on steep faces a vertical projection
		// (along the crest x height) rolling down the face with the roller
		// (from the normal of the wave itself: steep ripple facets must not switch the projection,
		// that drew combs of vertical streaks into the foam on flat water and on the swash)
		let steep = smoothstep( 0.82, 0.5, a.baseNormal.y );
		let ww = sat( a.fresh * 1.4 );
		// far pixels (a lace cell under a few pixels) only use the pattern's average (see "far" below):
		// skip the lace and whitewater lump lookups there
		let farOnly = a.footprint >= 0.12;
		var flat = vec4f( 0.5 );
		if ( ! farOnly ) { flat = surfFoamFlowLace( xz, flow, 0.0 ); }
		var lace = flat;
		// lumps of tumbling whitewater (~0.6 m), only where there is whitewater
		var lumps = 0.5;
		let tangent = vec2f( - dir.y, dir.x );
		// (compressed vertically: a front only a metre or two high must not show single lumps as columns)
		// (the along-crest coordinate warped by low-frequency noise: the 3.5 m lace tile must not repeat as a
		// row of identical lumps and spikes along the break)
		let al = dot( xz, tangent );
		let qv = vec2f( al + sin( al * 0.19 + 0.8 ) * 2.1 + sin( al * 0.47 + 2.9 ) * 0.6 + sin( P.y * 1.7 + al * 0.11 ) * 0.5, P.y * 1.1 );
		if ( steep > 0.01 && ! farOnly ) {
			let vert = surfFoamFlowLace( qv, vec2f( 0.0, -0.9 ), 1.0 );
			lace = mix( flat, vert, steep );
		}
		// Churning whitewater is a pile of foam lumps at several scales (tumbling masses ~1.3 m,
		// clumps ~0.5 m, bubble clusters ~0.2 m): a relief (m) for the normals, sunlit caps and
		// self-shadowed crevices (a short march toward the sun through the lump field)
		if ( ww > 0.02 && ! farOnly ) {
			let L = frame.sunDir;
			let pq = mix( xz, qv, steep );
			let pflow = mix( flow, vec2f( 0.0, -0.9 ), steep );
			let big = surfFoamBigAt( pq, pflow );
			let mid = sqrt( surfFoamFlowLace( pq / 2.2, pflow / 2.2, 3.0 ).x );
			lumps = big * 0.6 + mid * 0.4;
			let A = 0.22; // relief of the lumps (m)
			reliefPat = big * A + mid * ( A * 0.45 ) + ( 1.0 - lace.x ) * ( A * 0.12 );
			wwRelief = reliefPat * ww;
			// the sun direction in the pattern's coordinates, and its elevation above the local surface
			let Lp = mix( L.xz, vec2f( dot( L.xz, tangent ), L.y * 1.1 ), steep );
			let Ld = Lp / max( length( Lp ), 1e-3 );
			let NdL = dot( a.normal, L );
			let tanE = NdL / max( length( L - a.normal * NdL ), 0.05 );
			var occ = 0.0;
			let steps = array<f32, 3>( 0.14, 0.34, 0.7 );
			for ( var i = 0; i < 3; i++ ) {
				let d = steps[ i ];
				let hk = surfFoamBigAt( pq + Ld * d, pflow );
				occ = max( occ, smoothstep( 0.0, 0.05, ( hk - big ) * A - tanE * d ) );
			}
			wwShadow = 1.0 - occ * mix( 0.85, 0.7, steep );
			// crevices between the lumps: occluded from the sky too
			wwCav = mix( 0.5, 1.0, smoothstep( 0.05, 0.75, lumps ) );
		}

		// --- whitewater: the aerated mass of a roller / plunge / swash front. Dense and opaque, its
		// surface boiling: lumps with shaded crevices between them, bubble clusters on each; it only
		// tears (and shows water through) at its edges.
		let boil = lace.x * 0.7 + lace.z * 0.3;
		// (the edge of the churn is torn by its lumps: ragged fingers, not a clean boundary)
		let wwEdge = smoothstep( 0.25, 0.75, ww * 1.35 - boil * 0.3 - ( 1.0 - lumps ) * 0.5 );
		let whitewater = ( ww * 0.25 + wwEdge * 0.75 ) * ( ( 1.0 - boil ) * 0.12 + 0.88 );

		// --- foam carried by the water: a lacy web of bubble strands and clusters around holes. With
		// more foam the strands widen into a mat; as it spreads and thins it tears into filaments.
		// (w: strand half-width; the pattern covers 6% of the area at w = 0.1, 34% at 0.3, 82% at 0.6)
		let c = sat( ( a.sim + max( coverage - a.sim - a.fresh, 0.0 ) * 0.5 - 0.05 ) / 0.95 );
		// hole edges are ragged (bubble clusters), hole sizes vary between patches
		let w = max( pow( c, 1.4 ) * 0.9 * ( lace.z * 0.5 + 0.75 ) + ( lace.y - 0.5 ) * 0.06, 0.0 );
		let soft = 0.05 + a.footprint * 4.5;
		let mat = ( 1.0 - smoothstep( w - soft, w + soft, lace.x ) ) * smoothstep( 0.0, 0.05, c );
		// scattered bubbles in the holes next to the strands
		let bub = lace.y * smoothstep( w + 0.25, w, lace.x ) * smoothstep( 0.02, 0.2, c ) * 0.5;
		// thin foam is translucent and uneven, thick foam is opaque
		let inner = sat( ( w - lace.x ) / 0.25 );
		let laceFoam = max( mat * sat( inner * 0.35 + 0.45 + lace.z * 0.3 ), bub );

		// once a lace cell (~0.2 m) covers a few pixels, use the average of the pattern
		let far = smoothstep( 0.03, 0.12, a.footprint );
		let average = max( sat( pow( w, 1.45 ) * 1.9 ) * 0.8, ww * 0.95 );
		let near = max( laceFoam, whitewater );
		opacity = mix( a.foam, mix( near, average, far ), surf );

		// optical thickness (thin foam is translucent, thick foam scatters like snow) and a relief
		// height for the lighting: lumpy boiling whitewater, thick foam higher than its thin edges
		density = max( sat( c * 1.3 ) * ( inner * 0.5 + 0.5 ), ww );
		let reliefThin = inner * sat( c * 1.5 );
		let relief = reliefThin * ( 1.0 - ww );
		wwOut = ww * ( 1.0 - far * 0.6 );
		// far away the lumps average out: a mean shadowing of the churn instead
		wwShadow = mix( wwShadow, 0.82, far );
		wwCav = mix( wwCav, 0.8, far );
		wwRelief *= 1.0 - far;
		height = ( relief + a.bubbles * 0.15 ) * surf * ( 1.0 - far );
		reliefK = ww * ( 1.0 - far );
		thinPat = reliefThin;
		thinK = ( 1.0 - ww ) * surf * ( 1.0 - far );
		bubPat = a.bubbles * 0.15;
		bubK = surf * ( 1.0 - far );
	}

	return SurfFoamInfo( opacity, density, height, surf, wwOut, wwRelief, wwShadow, wwCav, reliefPat, reliefK, thinPat, thinK, bubPat, bubK );
}

// Foam radiance: a dense scatterer, wrapped diffuse sun (light diffuses through the bubbles),
// sky ambient, darker in the dips of the bubbly relief, glowing at thin edges when backlit.
fn surfFoamLight( info: SurfFoamInfo, N: vec3f, L: vec3f, V: vec3f, sun: vec3f, P: vec3f ) -> vec3f {
	let ww = info.ww;
	let cavity = info.cavity;
	// relief normal from the screen-space gradient of the height (Mikkelsen surface gradient): the
	// thin-foam relief (in units of ~3 cm) plus the whitewater lumps (m)
	// (gradients of the world-space patterns only, scaled by their weights: see SurfFoamInfo)
	let kb = ${ f( this.bump * 0.04 ) };
	let dpx = dpdx( P );
	let dpy = dpdy( P );
	let dhdx = dpdx( info.reliefPat ) * info.reliefK + ( dpdx( info.thinPat ) * info.thinK + dpdx( info.bubPat ) * info.bubK ) * kb;
	let dhdy = dpdy( info.reliefPat ) * info.reliefK + ( dpdy( info.thinPat ) * info.thinK + dpdy( info.bubPat ) * info.bubK ) * kb;
	let r1 = cross( dpy, N );
	let r2 = cross( N, dpx );
	let det = dot( dpx, r1 );
	let grad = ( r1 * dhdx + r2 * dhdy ) * sign( det );
	let Nf = normalize( N * abs( det ) - grad + N * 1e-6 );
	let NdL = dot( Nf, L );
	// foam lets light diffuse into it (wrapped lighting); churning whitewater much less so: its sides
	// facing away from the sun are shaded grey-blue by the sky, its caps sunlit, its crevices in the
	// shadow of the lumps around them
	let wrap = mix( 0.45, 0.12, ww );
	let diff = sat( NdL * ( 1.0 - wrap ) + wrap ) * mix( 1.0, info.selfShadow, ww );
	// dips between the lumps are shaded by the lumps around them (sky occlusion)
	let ao = mix( mix( 1.0, info.height * 0.3 + 0.76, info.surf ), cavity, ww );
	// light through thin aerated water (torn edges, thin foam, spray-soaked lips): green-white,
	// strongly forward scattered
	let thin = ( 1.0 - info.density ) * 0.8 + ww * ( 1.0 - cavity ) * 0.3;
	let trans = surfFoamPhaseHG( dot( - V, L ), 0.55 ) * thin * 1.3;
	let transCol = mix( vec3f( 1.0 ), vec3f( 0.6, 0.92, 0.82 ), ww * 0.7 + 0.3 );
	// light bounced around inside the churn (from its sunlit lumps) keeps the shaded foam from going
	// as dark and as blue as the open sky alone would make it
	let sky = frame.skyIrradiance;
	let skyGrey = vec3f( dot( sky, vec3f( 0.2126, 0.7152, 0.0722 ) ) );
	let amb = mix( sky, skyGrey, ww * 0.35 ) * ao + sun * ( ww * 0.05 ) * ao;
	return ( sun * ( diff * mix( 1.0, sqrt( cavity ), ww ) / PI + transCol * trans ) + amb ) * 0.86;
}
`;

	}

	// The former TSL hook ( surface.foamShading = ( args ) => surfFoam.shading( args ) ) is now the WGSL
	// surfFoamShading( SurfFoamArgs ) / surfFoamLight(); this returns the module that defines them.
	shading() {

		return this.module;

	}

}

import { UniformBlock, ShaderModule, SceneLighting } from '../engine/webgpu.js';
import { Texture } from '../engine/gpu/Texture.js';
import { ComputeKernel } from '../engine/gpu/Compute.js';
import { Vector2 } from '../engine/math/index.js';
import { commonModule } from '../engine/render/wgsl/common.js';
import { surfaceModule } from '../engine/render/wgsl/lighting.js';
import { FFT_SIZE } from './OceanFFT.js';

// The wave terms the lighting needs at a point depend on its xz only (surface height, slope and foam
// of the long waves, the mean level, the gust / slick factor of the caustics). They are baked once
// per frame into two camera-centred maps (0.25 m texels over 128 m, 2 m over 1 km, snapped to their
// texels so they don't crawl) instead of being evaluated by every fragment that can be under water
// (the FFT, shore wave and swash lookups). Beyond the far map: a flat sea. The material hooks only
// bind the maps; the FFT / shore / terrain helpers live in the bake kernels.
const MAP_N = 512;
const MAP_EXTENTS = [ 128, 1024 ];

// Installs the lighting hooks that every scene material uses:
//  - direct sun: attenuated along the refracted sun path through the water column (Beer-Lambert),
//    modulated by caustics that follow the waves above (swell + shore waves tilt the light, surf
//    foam and bubbles shade the floor)
//  - ambient: attenuated + tinted with depth
// Everything runs only for fragments that can be under water.
//
// Per material (material.underwaterLighting -> define UNDERWATER_LIGHTING): 'full' (2, default:
// terrain, reef, rocks - caustics, waves, foam shading), 'lite' (1, water column attenuation only:
// pier, boat hull, village) or 'none' (0, never under water: plants). The water itself (IS_WATER)
// is shaded by WaterMaterial and gets no modulation here.
//
// WGSL: installs `fn hookDirectModulation( P, N ) -> vec3f` and `fn hookAmbientModulation( P, N ) -> vec3f`
// (module prefix `underwater` for the bake helpers: underwaterLongWaves, underwaterMeanLevel; prefix
// `uwMap` for the baked map lookup: uwMapLookup( xz, waves ) -> UwMapSample).
// Note: unlike TSL, the modules' bindings (maps, caustics, terrain, clouds) are declared in every
// material that includes the lighting hooks, whatever its mode (the code itself is #if'd away).
export function installUnderwaterLighting( { fft, caustics, clouds = null, terrain = null, shore = null, surface = null, shoreSim = null } ) {

	const params = new UniformBlock( 'UnderwaterParams', {
		// highest the water can reach on the shore: the swash run-up grows with the surf height. Terrain
		// and props above it (the dry beach) skip the wave evaluation entirely.
		reach: [ 'f32', 3.0 ],
	}, { label: 'underwater' } );
	params.onBeforePack = () => {

		params.fields.reach.value = shore && shore.amplitude ? shore.amplitude.value * 1.5 + 1.2 : 3.0;

	};

	const T = !! terrain;
	const S = !! ( shore && terrain );
	const deps = [ commonModule, surfaceModule, fft.module, terrain && terrain.module, S && shore.module, shoreSim && shoreSim.module,
		caustics && caustics.module, clouds && clouds.module, surface && surface.attenuationModule ];

	const C3 = Math.min( 3, fft.cascades ), C2 = Math.min( 2, fft.cascades );

	const helpers = new ShaderModule( {
		name: 'underwater',
		deps,
		uniforms: params,
		uniformName: 'underwater',
		code: /* wgsl */`
struct UnderwaterLongWaves { height: f32, slope: vec2f, foam: f32 };

// long waves at xz: height, slope and foam from the coarse FFT cascades and the shore waves
// texel: the bake's texel size (m); the cascades are read no finer than it (level >= 2)
fn underwaterLongWaves( xz: vec2f, texel: f32 ) -> UnderwaterLongWaves {
	let seaDepth = ${ T ? 'frame.seaLevel - terrainHeightAt( xz )' : '50.0' };
	var h = 0.0;
	var slope = vec2f( 0.0 );
	for ( var c = 0; c < ${ C3 }; c++ ) {
		let uv = xz / ocean.sizes[ c ].x;
		let att = ${ surface ? 'waterSurfaceCascadeAttenuation( c, seaDepth )' : '1.0' };
		let lvl = max( 2.0, log2( texel * ${ FFT_SIZE }.0 / ocean.sizes[ c ].x ) );
		h += textureSampleLevel( oceanDisplacement, smpLinearRepeat, uv, c, lvl ).y * att;
		if ( c < 2 ) {
			let d = textureSampleLevel( oceanDerivatives, smpLinearRepeat, uv, c, lvl );
			slope += vec2f( d.x, d.y ) * att;
		}
	}

	var foam = 0.0;
${ S ? `	{
		let sw = shoreEvaluate( xz, seaDepth, terrainHeightAt( xz ) );
		h += sw.disp.y;
		let n = sw.nShore;
		slope += - vec2f( n.x, n.z ) / max( n.y, 0.25 );
		foam += sw.foam;
	}` : '' }
${ shoreSim ? '	foam += shoreSimSample( xz ).x * 0.8;' : '' }
	// waves only exist over water: none over dry land
${ T ? '	h = h * smoothstep( 0.0, 1.0, seaDepth ) - smoothstep( 0.0, -0.4, seaDepth ) * 10.0;' : '' }
	var o: UnderwaterLongWaves;
	o.height = frame.seaLevel + h;
	o.slope = slope;
	o.foam = foam;
	return o;
}

fn underwaterSigT() -> vec3f { return frame.waterAbsorption + frame.waterScattering; }

// mean water level from the two longest FFT cascades (one texture binding)
fn underwaterMeanLevel( xz: vec2f ) -> f32 {
	var h = 0.0;
	for ( var c = 0; c < ${ C2 }; c++ ) {
		h += textureSampleLevel( oceanDisplacement, smpLinearRepeat, xz / ocean.sizes[ c ].x, c, 3.0 ).y;
	}
${ T ? '	h *= smoothstep( 0.0, 3.0, frame.seaLevel - terrainHeightAt( xz ) );' : '' }
	return frame.seaLevel + h;
}
`,
	} );

	// ---- the baked maps: A = ( height - sea level, slope.xy, foam ), B = ( mean level - sea level, detail k )
	const mapParams = new UniformBlock( 'UwMapParams', {
		origin0: [ 'vec2f', new Vector2() ],
		origin1: [ 'vec2f', new Vector2() ],
		// highest the water can reach on the shore (see params.reach): the hooks' cheap reject
		reach: [ 'f32', 3.0 ],
	}, { label: 'uwMap' } );
	mapParams.onBeforePack = () => {

		mapParams.fields.reach.value = shore && shore.amplitude ? shore.amplitude.value * 1.5 + 1.2 : 3.0;

	};
	const origins = [ mapParams.fields.origin0, mapParams.fields.origin1 ];
	const make = ( name ) => new Texture( { label: name, width: MAP_N, height: MAP_N, format: 'rgba16float', usage: [ 'sample', 'storage' ] } );
	const levels = MAP_EXTENTS.map( ( extent, l ) => {

		const texel = extent / MAP_N;
		const A = make( 'uwWaves' + l ), B = make( 'uwLevel' + l );
		const kernel = new ComputeKernel( {
			label: 'Underwater Light Map ' + l,
			modules: [ helpers, ...( caustics && caustics.module ? [ caustics.module ] : [] ) ],
			bindings: { uwMapParams: { uniform: mapParams }, uwOutA: { storageTexture: A, access: 'write' }, uwOutB: { storageTexture: B, access: 'write' } },
			workgroupSize: [ 8, 8, 1 ],
			code: /* wgsl */`
@compute @workgroup_size( WG_X, WG_Y, WG_Z )
fn main( @builtin( global_invocation_id ) gid: vec3u ) {
	let xz = ( vec2f( gid.xy ) + 0.5 ) * ${ texel } + uwMapParams.origin${ l };
	let lw = underwaterLongWaves( xz, ${ texel } );
	textureStore( uwOutA, vec2u( gid.xy ), vec4f( lw.height - frame.seaLevel, lw.slope, sat( lw.foam ) ) );
	let dk = ${ caustics && caustics.module ? 'causticsDetailK( xz )' : '1.0' };
	textureStore( uwOutB, vec2u( gid.xy ), vec4f( underwaterMeanLevel( xz ) - frame.seaLevel, dk, 0.0, 1.0 ) );
}
`,
		} );
		return { extent, texel, A, B, kernel, origin: origins[ l ] };

	} );

	const [ L0, L1 ] = levels;
	const mapModule = new ShaderModule( {
		name: 'uwMap',
		deps: [ commonModule ],
		uniforms: mapParams,
		uniformName: 'uwMapParams',
		bindings: { uwWaves0: { texture: L0.A }, uwLevel0: { texture: L0.B }, uwWaves1: { texture: L1.A }, uwLevel1: { texture: L1.B } },
		code: /* wgsl */`
struct UwMapSample { height: f32, slope: vec2f, foam: f32, mean: f32, detailK: f32 };

fn uwReach() -> f32 { return uwMapParams.reach; }

// bilinear lookup of the baked maps at xz (near map first, then far; flat sea beyond).
// waves: map A (height, slope, foam) is only read for the full direct term
fn uwMapLookup( xz: vec2f, waves: bool ) -> UwMapSample {
	var a = vec4f( 0.0 );
	var b = vec4f( 0.0, 0.9, 0.0, 0.0 );
	let st0 = ( xz - uwMapParams.origin0 ) / ${ L0.texel };
	let st1 = ( xz - uwMapParams.origin1 ) / ${ L1.texel };
	if ( all( st0 > vec2f( 0.5 ) ) && all( st0 < vec2f( ${ MAP_N }.0 - 0.5 ) ) ) {
		let uv = st0 / ${ MAP_N }.0;
		if ( waves ) { a = textureSampleLevel( uwWaves0, smpLinearClamp, uv, 0.0 ); }
		b = textureSampleLevel( uwLevel0, smpLinearClamp, uv, 0.0 );
	} else if ( all( st1 > vec2f( 0.5 ) ) && all( st1 < vec2f( ${ MAP_N }.0 - 0.5 ) ) ) {
		let uv = st1 / ${ MAP_N }.0;
		if ( waves ) { a = textureSampleLevel( uwWaves1, smpLinearClamp, uv, 0.0 ); }
		b = textureSampleLevel( uwLevel1, smpLinearClamp, uv, 0.0 );
	}
	return UwMapSample( frame.seaLevel + a.x, a.yz, a.w, frame.seaLevel + b.x, b.y );
}
`,
	} );

	const update = ( camera ) => {

		for ( const lv of levels ) {

			// snapped to whole texels: the texel centres stay fixed in the world
			const half = lv.extent / 2;
			lv.origin.value.set(
				Math.floor( camera.position.x / lv.texel ) * lv.texel - half,
				Math.floor( camera.position.z / lv.texel ) * lv.texel - half,
			);

		}

		for ( const lv of levels ) lv.kernel.dispatch( [ MAP_N / 8, MAP_N / 8, 1 ] );

	};

	// the hooks bind only the maps (+ caustics, clouds, terrain hill shadow)
	const hookDeps = [ commonModule, surfaceModule, mapModule, caustics && caustics.module, clouds && clouds.module, terrain && terrain.module ].filter( Boolean );

	const direct = new ShaderModule( {
		name: 'hook-directModulation-underwater',
		deps: hookDeps,
		code: /* wgsl */`
fn hookDirectModulation( P: vec3f, N: vec3f ) -> vec3f {
#if IS_WATER
	return vec3f( 1.0 );
#else
	var result = vec3f( 1.0 );
#if UNDERWATER_LIGHTING == 2
	// the pixel's footprint on the ground plane, to filter the caustics over it (taken here, in
	// uniform control flow, ahead of the branches below)
	let gdx = dpdx( P.xz );
	let gdy = dpdy( P.xz );
#endif
#if UNDERWATER_LIGHTING != 0
	// cheap reject: above anything the water reaches
	if ( P.y < frame.seaLevel + uwReach() ) {
#if UNDERWATER_LIGHTING == 2
		let lw = uwMapLookup( P.xz, true );
		let lwHeight = lw.height;
#else
		let lwHeight = uwMapLookup( P.xz, false ).mean;
#endif
		let d = max( lwHeight - P.y, 0.0 );
		if ( d > 0.0 ) {
			let under = smoothstep( 0.0, 0.08, d );
			let Ls = refract( - frame.sunDir, vec3f( 0.0, 1.0, 0.0 ), 1.0 / 1.333 );
			let mu = max( - Ls.y, 0.15 );
			let atten = exp( - ( frame.waterAbsorption + frame.waterScattering ) * d / mu );
#if UNDERWATER_LIGHTING == 2
#if REFRACTION_CLIP
			// the refraction source is half resolution and seen blurred: no dispersion
			let caust = ${ caustics ? 'causticsSampleBakedMono( P, d, lw.slope, lw.foam, gdx, gdy, lw.detailK )' : 'vec3f( 1.0 )' };
#else
			let caust = ${ caustics ? 'causticsSampleBaked( P, d, lw.slope, lw.foam, gdx, gdy, lw.detailK )' : 'vec3f( 1.0 )' };
#endif
#else
			let caust = vec3f( 1.0 );
#endif
			result = mix( vec3f( 1.0 ), atten * caust, under );
		}
	}
#endif
	let cloudShadow = ${ clouds ? 'cloudsShadow( P.xz )' : '1.0' };
	// hills shadowing the island and the bay at low sun (terrain heightfield shadow; the terrain and
	// the rocks apply it in their own lighting model)
#if HILL_SHADOW_SELF
	let hill = 1.0;
#else
	let hill = ${ T ? 'terrainSunShadowAt( P )' : '1.0' };
#endif
	return result * cloudShadow * hill;
#endif
}
`,
	} );

	const ambient = new ShaderModule( {
		name: 'hook-ambientModulation-underwater',
		deps: [ direct ],
		code: /* wgsl */`
fn hookAmbientModulation( P: vec3f, N: vec3f ) -> vec3f {
	var result = vec3f( 1.0 );
#if !IS_WATER
#if UNDERWATER_LIGHTING != 0
	if ( P.y < frame.seaLevel + uwReach() ) {
		// the ambient term only needs the mean water level (no shore evaluation)
		let d = max( uwMapLookup( P.xz, false ).mean - P.y, 0.0 );
		let under = smoothstep( 0.0, 0.1, d );
		// diffuse downwelling light: effective path ~1.2x depth, plus a little in-scattered blue
		let atten = exp( - ( frame.waterAbsorption + frame.waterScattering ) * d * 1.2 ) * 0.85 + vec3f( 0.0, 0.02, 0.04 ) * exp( d * -0.1 );
		result = mix( vec3f( 1.0 ), atten, under );
	}
#endif
#endif
	return result;
}
`,
	} );

	// Sun shadows of underwater receivers are looked up where their light entered the water: back up
	// the refracted sun ray (through the local wave slope) to the surface. Shadows of the pier, the boat
	// or rocks above the water then land where refraction puts them (closer under the object than the
	// straight sun ray would), sway with the waves, and blur with depth (forward scattering: the entry
	// point is jittered over a disk that grows with the depth, the temporal resolve averages it).
	const shadowPos = new ShaderModule( {
		name: 'hook-shadowPosition-underwater',
		deps: hookDeps,
		code: /* wgsl */`
fn hookShadowPosition( P: vec3f, N: vec3f, pixel: vec2f ) -> vec3f {
#if IS_WATER || UNDERWATER_LIGHTING == 0
	return P;
#else
	if ( P.y >= frame.seaLevel + uwReach() ) { return P; }
#if UNDERWATER_LIGHTING == 2
	let m = uwMapLookup( P.xz, true );
	let h = m.height;
	let n = normalize( vec3f( - m.slope.x, 1.0, - m.slope.y ) );
#else
	let h = uwMapLookup( P.xz, false ).mean;
	let n = vec3f( 0.0, 1.0, 0.0 );
#endif
	let d = h - P.y;
	if ( d <= 0.0 ) { return P; }
	let up = - refract( - frame.sunDir, n, 1.0 / 1.333 ); // toward the entry point, in the water
	let entry = P + up * ( d / max( up.y, 0.15 ) );
	let g = interleavedGradientNoise( pixel + f32( frame.frameIndex % 64u ) * 5.588238 );
	let phi = g * TWO_PI;
	let rad = sqrt( fract( g * 1.618034 + 0.31 ) ) * min( d * 0.05, 0.5 );
	return entry + vec3f( cos( phi ), 0.0, sin( phi ) ) * rad;
#endif
}
`,
	} );

	SceneLighting.set( 'directModulation', direct );
	SceneLighting.set( 'shadowPosition', shadowPos );
	SceneLighting.set( 'ambientModulation', ambient );
	return { helpers, direct, ambient, shadowPos, params, update, levels };

}

import { Vector2, Vector3, Vector4, MathUtils, DataUtils } from '../engine/index.js';
import { GPU, UniformBlock, Texture, StorageBuffer, ShaderModule, ComputeKernel, commonModule } from '../engine/webgpu.js';
import { GRAVITY } from '../core/Globals.js';

const N = 512; // grid cells per side
const LOG2N = 9;
const HALF = N / 2;
const MASK = N - 1;
const CELL = 0.4; // m
const SIZE = N * CELL; // window size (m)
// reference depths of the four spectral operators (m); a cell blends the two bracketing its depth
const DEPTHS = [ Infinity, 6, 1.8, 0.6 ];
const SPONGE = 22; // absorbing band at the window edges (cells)
// boat-frame box of the near-field template (steady wave pattern under the hull)
const TW = 32, TH = 88; // 0.1 m texels (steep pressure near the stem: keep resampling errors small)
const TX0 = - 1.6, TX1 = 1.6, TZ0 = - 4.4, TZ1 = 4.4;

// WGSL float literal
const f = ( x ) => {

	const s = String( x );
	return /[.e]/.test( s ) ? s : s + '.0';

};

// Interactive boat wake: a linear free-surface wave simulation with exact dispersion.
//
// Height h and vertical velocity w on a 512^2 grid (0.4 m cells, 205 m) in a window that follows
// the boat. The window is addressed toroidally (world cell I lives in texel I mod N): it scrolls
// by whole cells without moving any data, and the FFT's periodicity is the addressing itself.
// Each step is 3 dispatches in one compute pass (~0.13 ms on an M5 Pro):
//   1. rows: per-cell physics (hull pressure, dissipation, breaking, foam, obstacles), display
//      texture, forward FFT along x
//   2. columns: forward FFT along z, spectral operators, inverse FFT along z (spare workgroups
//      update the boat's near-field template)
//   3. rows: inverse FFT along x, symplectic Euler step, absorbing sponge at the window edges
//
// Waves: dw/dt = -g L[h + P], dh/dt = w. L = |k| tanh(|k| d) is the Dirichlet-to-Neumann operator of
// linear water waves; P is the pressure head of the hull (the boat is a moving pressure
// distribution, after Havelock): its immersion, a dynamic part ~U^2/2g where the hull enters the
// water and the hollow behind the transom at speed. Deep water gives the Kelvin wake (transverse
// and divergent waves inside 19.5 deg, narrowing at high Froude numbers) for any course and speed.
// Variable depth: four spectral operators (d = inf, 6, 1.8, 0.6 m) are blended per cell in the
// symmetric form sum_i s_i L_i[s_i u] (the two levels bracketing the local depth; <= 5 % phase
// speed error for 1-100 m waves down to 0.5 m depth). It is self-adjoint, so wake waves slow
// down, shorten, refract and grow over the shoaling beach until they break in the swash zone.
// Dissipation is a turbulent eddy viscosity in flux form (conserves mass): breaking crests, the
// surf and the propeller wash feed the turbulence, which flattens the waves it passes through.
// Dry land and the pier piles are rigid (weak reflection, scattering around the piles).
//
// Output (display texture, rgba16f): (h, dh/dx, dh/dz, foam), read by WaterSurface through
// displacement() / fragment() (one sampler per shader stage), plus the aeration (bubbles in the
// water column, a slower field than the surface foam: fragment().aeration, 0..aerOut), read with
// textureLoad (no sampler).
//
// WGSL (this.module, prefix `wake`):
//   fn wakeDisplacement( xz: vec2f ) -> vec3f        displacement of the wake surface at world xz
//   struct WakeFrag { slopes: vec2f, foam: f32, aeration: f32 }
//   fn wakeFragment( xz: vec2f ) -> WakeFrag          slopes (dh/dx, dh/dz), foam, aeration (0..aerOut)
//   fn wakeHeight( xz: vec2f ) -> f32, fn wakeSample( xz: vec2f ) -> vec4f, fn wakeAeration( xz: vec2f ) -> f32
// Consumes terrainHeightAt( xz: vec2f ) -> f32 from terrainGPU.module (compute kernels only).
//
// Port note: the simulation kernels read their parameters from their own uniform block
// (WakeKernel, `wk`); the readers use WakeParams, whose fields share the same `{ value }` handles.
// A uniform buffer holds one value per submit, and `reset` is cleared after the step while the
// water is drawn later in the same frame.
export class WakeSim {

	constructor( renderer, { terrainGPU, boat, colliders = null } ) {

		this.renderer = renderer;
		this.terrain = terrainGPU;
		this.boat = boat;
		this.lines = boat.model.lines;

		const K = this.kernelParams = new UniformBlock( 'WakeKernel', {
			origin: [ 'vec2f', new Vector2() ], // min corner, cells
			prev: [ 'vec2f', new Vector2() ], // min corner last step
			center: [ 'vec2f', new Vector2() ], // world centre (m)
			boatPos: [ 'vec2f', new Vector2() ],
			boatRot: [ 'vec2f', new Vector2( 1, 0 ) ], // cos, sin yaw
			dead: [ 'vec2f', new Vector2( 0.03, 0.08 ) ], // residual dead zone (m)
			trim: [ 'vec3f', new Vector3() ], // immersion change: c + a x + b z
			reset: [ 'f32', 1 ],
			pileBox: [ 'vec4f', new Vector4( 0, 0, 1, 1 ) ],
			dt: [ 'f32', 1 / 60 ],
			amount: [ 'f32', 0 ],
			source: [ 'f32', 1 ], // pressure gain
			wash: [ 'f32', 0 ], // propeller wash / transom turbulence
			bow: [ 'f32', 0 ], // breaking bow wave
			speed: [ 'f32', 0 ],
			washW: [ 'f32', 0.6 ], // half width of the wash at the transom
			boil: [ 'f32', 1.2 ], // turbulent stirring of the surface (boils)
			visc: [ 'f32', 0.006 ], // m^2/s, damps grid-scale waves (~k^2)
