			hollow: [ 'f32', 1 ], // length of the transom hollow (m)
			hollowK: [ 'f32', 0 ],
			amplitude: [ 'f32', 1 ],
			foamGain: [ 'f32', 0.35 ], // thick churn at the transom, patchy lace behind
			aerGain: [ 'f32', 1 ],
