		}, { label: 'wake kernel params' } );
		const R = this.readerParams = new UniformBlock( 'WakeParams', {
			center: 'vec2f', boatPos: 'vec2f', boatRot: 'vec2f', dead: 'vec2f',
			amount: 'f32', amplitude: 'f32', aerOut: 'f32',
