fn wakeInTemplate( tc: vec2f ) -> bool { return tc.x > 0.0 && tc.y > 0.0 && tc.x < ${ f( TW - 1 ) } && tc.y < ${ f( TH - 1 ) }; }

fn wakeSample( xz: vec2f ) -> vec4f {
